-- 233: Cosmic Education LPM moves into OpenLPM as a human-curated project space with an English and a German space (Dustin, 2026-11-07).
--
-- Source: the standalone cosmic-education-k12 folder (a draft LPM on Montessori's Five Great Lessons, drafted 2026-09-11 for a
-- doctoral project at Martin-Luther-Universitaet Halle-Wittenberg). Same shape as the Bee LPM move (migration 128): a parent container plus two
-- independent child spaces linked only by parent_project_id, so each language can be curated on its own.
--
-- Label: epistemic_status = 'in-development' (shows as Human-Curated). That states the aim of the space. It does not say a person has reviewed
-- the content. Nobody has. The draft itself says the Cosmic Education progression is a designed thought experiment that has not been tested
-- against children's reasoning. Every strand, stage and indicator row carries content.review.state = 'unreviewed'. Both child spaces are private, maturity draft.
--
-- Contents per language space: 14 concepts (10 Cosmic Education concepts + 4 imported by id from ConceptBase), 5 strands, 35 stages (7 age bands each),
-- 50 performance indicators as separate rows (so each can be reviewed and commented on alone), 90 connections, 32 concept tags.
-- The 41 curriculum crosswalk entries (Sachsen, Sachsen-Anhalt, Thueringen, GDSU Perspektivrahmen, Montessori tradition, IB PYP, Big History Project) sit in
-- each matching stage's content.crosswalks, each with its own confirmed / uncertain mark. The seven systems are listed under Sources.
-- Base-repo links: ConceptBase (4 concepts by id), TheoryBase (selection-teleology proposition, learning progressions as scientific models),
-- LiteratureBase (Kelemen & Rosset 2009, Kampourakis 2020). Links to the Thueringen curriculum structure overview are NOT made here; they would be a
-- separate proposal pass like migration 225.
--
-- German wording: the draft had German labels, descriptions, essential questions and crosswalk notes, but English-only indicators and concept
-- definitions. The German space uses a German wording of those written by Claude (scripts/data/cosmic_education_de.json), marked unreviewed.
-- The 4 imported ConceptBase definitions stay English (ConceptBase has no German wording).
--
-- Idempotent: uuid5 ids, ON CONFLICT DO NOTHING. Generated by scripts/generate_cosmic_education_lpm_seed.mjs; do not hand-edit.
-- Rollback: DELETE FROM projects WHERE slug IN ('cosmic-education-lpm-en','cosmic-education-lpm-de','cosmic-education-lpm'); (children cascade).
SET search_path = public, extensions;

DO $MIGRATION$
DECLARE
  v_parent UUID := '697fbd92-6005-5dcc-be82-8ab1851d6039';
  v_en UUID := '6ed3414d-dab3-5cac-8eed-e3fd38099699';
  v_de UUID := 'e41dabbe-ffa4-56d6-a5f1-f05075f5c8ce';
  v_user UUID;
BEGIN
  SELECT id INTO v_user FROM users WHERE email = 'dustin.eirdosh@eva.mpg.de';

  VALUES (v_parent, 'cosmic-education-lpm', $J$Cosmic Education LPM$J$, $J$A five-strand learning progression built on Maria Montessori's Cosmic Education (the Five Great Lessons): the Story of the Universe, of Life, of Humans, of Language and of Numbers. Montessori's own scope is ages 6 to 12; the space also holds an informal early-childhood stage and hand-off stages for older learners. Organizational home only: the content lives in the English and German child spaces.$J$, 'active', 'in-development',
    $J$Human-curated by aim. Moved from the standalone cosmic-education-k12 draft. No expert has reviewed the content yet, and the progression has not been tested against children's reasoning.$J$,
    'hosted', TRUE, 'draft', NULL, 'thematic', '{}'::TEXT[], ARRAY['montessori','cosmic-education','interdisciplinary']::TEXT[], ARRAY['en','de']::TEXT[])
  ON CONFLICT (slug) DO NOTHING;
  IF v_user IS NOT NULL THEN
    UPDATE projects SET created_by = v_user WHERE id = v_parent AND created_by IS NULL;
  END IF;

  -- ====================================================================
  -- Cosmic Education LPM (English)
  -- ====================================================================
  VALUES (v_en, 'cosmic-education-lpm-en', $J$Cosmic Education LPM (English)$J$, $J$The English space of the Cosmic Education LPM: five strands, one per Great Lesson (Universe, Life, Humans, Language, Numbers), each over seven age bands from early childhood to upper secondary. Montessori's own scope is ages 6 to 12 (bands GB-1 to GB-3); the other bands are an informal early stage and hand-offs to other models. Crosswalks to Sachsen, Sachsen-Anhalt and Thueringen primary curricula, the GDSU Perspektivrahmen, Montessori's own tradition, IB PYP and the Big History Project are stored with each stage.$J$, 'active', 'in-development',
    $J$Human-curated by aim; to be reviewed and curated in OpenLPM. Moved from the cosmic-education-k12 draft on 2026-11-07. No expert has reviewed it, and the progression has not been tested against children's reasoning.$J$,
    'hosted', TRUE, 'draft', v_parent, 'thematic', '{}'::TEXT[], ARRAY['montessori','cosmic-education','interdisciplinary']::TEXT[], ARRAY['en']::TEXT[])
  ON CONFLICT (slug) DO NOTHING;


  SELECT v_en, $J$cosmic-education-k12 (draft folder, moved into this space)$J$, $J$YAML (ConceptBase oe:LPM / oe:Strand shape)$J$, $J$CC-BY-NC-SA-4.0 (the draft's own LICENSE). Structurally imported by this migration.$J$, NULL
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_en AND source_name = $J$cosmic-education-k12 (draft folder, moved into this space)$J$);
  SELECT v_en, $J$Crosswalk: OER Project — Big History Project (Eight Thresholds)$J$, $J$Crosswalk table (state-standards)$J$, $J$The OER Project's Big History Project (free, teacher-registration-required, high-school-level) organizes 13.8 billion years of history around eight 'Thresholds of increasing complexity,' each requiring 'Goldilocks Conditions' for the next to emerge, confirmed this session: the Big Bang; Stars Light Up; New Chemical Elements; Earth and the Solar System; Life on Earth; Collective Learning; Agriculture; the Modern Revolution — taught across ten units, with Units 8-10 (Expansion and Interconnection; Acceleration; the Future) threaded through the rest. Deliberately included as this LPM's only GB-4+ crosswalk content: unlike this LPM's own GB-4/5/6 bands (which stay empty and hand off elsewhere, per Montessori's own claimed 6-12 scope), Big History Project is a real, independently developed secondary-level curriculum that picks up structurally similar content (universe/life/human-history 'big picture' narrative) at exactly the age this LPM's own strands stop — worth naming as a genuine continuation path for a school wanting to extend a Cosmic-Education-rooted sequence past age 12 without switching to a completely disconnected narrative frame.$J$, NULL
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_en AND source_name = $J$Crosswalk: OER Project — Big History Project (Eight Thresholds)$J$);
  SELECT v_en, $J$Crosswalk: GDSU Perspektivrahmen Sachunterricht (national didactic framework)$J$, $J$Crosswalk table (national-framework)$J$, $J$The Gesellschaft für Didaktik des Sachunterrichts (GDSU) publishes the Perspektivrahmen Sachunterricht (2002, fully revised 2013; a further full revision is 'in Vorbereitung' as of this session per the GDSU Journal's own bibliography) — the professional-consensus framework most German Länder's own Sachunterricht/Heimat- und Sachkunde Lehrpläne draw on, without itself being any one Land's binding law. This crosswalk's structure comes from two confirmed sources fetched this session: (1) Peschel, Goll & Schomaker (2026), 'Vielperspektivität und Vernetzung: Zentrale Prinzipien des Sachunterrichts,' GDSU-Journal April 2026 Heft 16 — confirmed directly, giving this crosswalk's own emphasis on Vielperspektivität (multi-perspectivity) and Vernetzung (networking/connecting) as the framework's two named leading principles, and its real, current list of Perspektivenvernetzende Themenbereiche (PVTs, perspective-linking topic areas): Nachhaltigkeitsthemen (Klimawandel, globale Gerechtigkeit), Digitalisierung und Medien, Gesundheit, Mobilität, Identität, Frieden, Demokratie; (2) the Perspektivrahmen's five underlying subject perspectives are NOT independently confirmed from the Perspektivrahmen document itself in this session — they are inferred from Sachsen-Anhalt's own confirmed Fachlehrplan structure (which is explicitly built on the GDSU framework) mapping closely onto the standard naturwissenschaftlich/raumbezogen/historisch/sozialwissenschaftlich/technisch five-perspective structure widely cited in Sachunterricht didactics literature. Flagged as an inference, not a direct citation, per this ecosystem's own verify-before-canonical-record discipline.$J$, NULL
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_en AND source_name = $J$Crosswalk: GDSU Perspektivrahmen Sachunterricht (national didactic framework)$J$);
  SELECT v_en, $J$Crosswalk: IB Primary Years Programme — Six Transdisciplinary Themes$J$, $J$Crosswalk table (state-standards)$J$, $J$The International Baccalaureate's Primary Years Programme (PYP) organizes its entire curriculum around six transdisciplinary themes, confirmed this session: Who We Are; Where We Are in Place and Time; How We Express Ourselves; How the World Works; How We Organize Ourselves; Sharing the Planet. A revised set of theme descriptors was confirmed as real and current (schools may adopt now; all PYP schools required to by September 2027) — the revision's own stated direction, per the source fetched, is to broaden each theme's scope to include and honor the natural world alongside human experience, moving central ideas that once focused only on human migration or human systems toward including how ecosystems themselves migrate, adapt, and organize. This is independently the same direction Cosmic Education has taken from the start (a story that includes the non-human physical and biological world as a full partner, not backdrop, to the human story) — a real convergence worth naming, not one either source claims about the other. The exact revised descriptor text itself was not independently fetched this session — flagged uncertain.$J$, NULL
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_en AND source_name = $J$Crosswalk: IB Primary Years Programme — Six Transdisciplinary Themes$J$);
  SELECT v_en, $J$Crosswalk: Montessori Cosmic Education (native tradition)$J$, $J$Crosswalk table (pedagogical-tradition)$J$, $J$This LPM's own primary source, not a secondary crosswalk in the usual sense — included as a formal crosswalk anyway so the app's Standards Crosswalks feature can show, side by side, how far a school actually implementing Montessori's own materials (the Global Montessori Network's published Great Lessons resources; the widely-documented Timeline of Life, Clock of Eras, Long Black Line, and Fundamental Needs Chart materials) tracks against this LPM's own strand/gradeband structure. High confidence throughout: these are Montessori's own named materials, not this LPM's invention.$J$, NULL
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_en AND source_name = $J$Crosswalk: Montessori Cosmic Education (native tradition)$J$);
  SELECT v_en, $J$Crosswalk: Saxony-Anhalt Primary Curriculum (Fachlehrplan Grundschule Sachunterricht)$J$, $J$Crosswalk table (state-standards)$J$, $J$Extracted directly from LISA's (Landesinstitut für Schulqualität und Lehrerbildung Sachsen-Anhalt) official PDF, Stand 01.08.2019, fetched and parsed 2026-09-11: the 3 Prozessbezogene Kompetenzen (Erkunden; Kommunizieren und Argumentieren; Präsentieren) and the 5 Inhaltsbezogene Kompetenzbereiche (Sozial- und kulturwissenschaftlicher Bereich; Raumbezogener Bereich; Verkehrsbezogener Bereich; Naturwissenschaftlicher Bereich; Historischer Bereich), each specified as an end-of-Schuljahrgang-2 and end-of-Schuljahrgang-4 competency level. A newer Anhörungsfassung (consultation draft) exists as of this session but could not be extracted — this crosswalk is built on the confirmed, currently-in-force 2019 version.$J$, NULL
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_en AND source_name = $J$Crosswalk: Saxony-Anhalt Primary Curriculum (Fachlehrplan Grundschule Sachunterricht)$J$);
  SELECT v_en, $J$Crosswalk: Saxony Primary Curriculum (Lehrplan Grundschule Sachunterricht)$J$, $J$Crosswalk table (state-standards)$J$, $J$Extracted directly from the Sächsisches Schulportal's live Lehrplan database (schulportal.sachsen.de/lplandb/lehrplan/80), fetched 2026-09-11: the six Lernbereiche and their instructional-hour allocations for Klassenstufen 1/2, 3, and 4, plus each Klassenstufe's named Wahlbereiche (elective units).$J$, $J$https://schulportal.sachsen.de/lplandb/lehrplan/80$J$
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_en AND source_name = $J$Crosswalk: Saxony Primary Curriculum (Lehrplan Grundschule Sachunterricht)$J$);
  SELECT v_en, $J$Crosswalk: Thuringia Primary Curriculum (Lehrplan Heimat- und Sachkunde)$J$, $J$Crosswalk table (state-standards)$J$, $J$PARTIAL CONFIDENCE, flagged honestly rather than filled in: the Thüringer Schulportal confirms three Lernbereiche — Natur und Technik; Raum und Zeit; Lebewesen und Lebensräume — from two independent search results this session, but the source PDF (thue-lp-heisa-grundschule.pdf) could not be decoded this session (its text stream returned as unreadable binary/LZW-compressed content to the fetch tool used), so no per-Klassenstufe competency detail below is confirmed. Every mapping below is confidence: uncertain for this reason, not because the underlying match is implausible — a follow-up pass with a working PDF extraction path (the same pypdf-based approach used successfully for the Sachsen-Anhalt Lehrplan in this same session) would very likely resolve most of these to confirmed.$J$, NULL
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_en AND source_name = $J$Crosswalk: Thuringia Primary Curriculum (Lehrplan Heimat- und Sachkunde)$J$);

  IF v_user IS NOT NULL THEN
    UPDATE projects SET created_by = v_user WHERE id = v_en AND created_by IS NULL;
  END IF;


Evolutionary-biology caveat: Read as a literal causal claim ("a bee's stripes exist because the ecosystem needs pollinators"), this is design teleology — the explanatory pattern evolution education treats as a persistent, well-documented misconception (Kelemen 2009, "promiscuous teleology"). This ecosystem's own recorded position (theorybase:OE-PROPOSITION-selection-teleology-legitimate) is that purposive language is defensible when it tracks selection teleology (a trait persists BECAUSE of the differential survival/reproduction its effects produced across generations) and not defensible when it tracks design teleology (a trait exists BECAUSE something needed or intended it). Whether Montessori's own Cosmic Task framing, as actually delivered in real classrooms, produces one kind of reasoning or the other in children is an open empirical question, not yet studied — see this LPM's own README for why that question is this LPM's central research opportunity, not a defect to design around silently.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-cosmic-task","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["montessori-pedagogy","evolutionary-biology-caveat"],"examples":["Earthworms aerate soil, which helps plants grow, which feeds animals that return nutrients to soil.","A child asked to name their own 'task' within their family or classroom, as a felt, child-scale entry point before any biological claim is made."],"nonExamples":["A trait exists because the species needs it to survive (design teleology, not selection teleology — the distinction this concept exists to make visible, not to ignore)."],"relations":{"skos:related":["OE-CONCEPT-cosmic-k12-interconnectedness","OE-CONCEPT-oe-interdisciplinary-evolutionary-process"]},"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('83dd5cab-304c-5b4b-94ca-9768cb6d6d84', v_en, 'concept', $J$Interconnectedness$J$, $J$The idea, central to Cosmic Education and independently central to Germany's own Sachunterricht didactics (Vielperspektivität und Vernetzung — Peschel, Goll & Schomaker 2026, GDSU Journal Heft 16), that no single phenomenon is fully understood from one disciplinary angle alone, and that a full picture requires actively relating multiple perspectives to each other rather than presenting them side by side.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-interconnectedness","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["general"],"examples":["A river connects geology (where the water flows), biology (what lives in it), history (why a town was built beside it), and economics (how it is used today)."],"nonExamples":[],"relations":{"skos:broader":["OE-CONCEPT-cosmic-k12-cosmic-task"],"skos:related":["OE-CONCEPT-oe-interdisciplinary-evolutionary-process"]},"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('41969baa-d0ce-5bb9-a515-ddd4f3ede140', v_en, 'concept', $J$Great Story$J$, $J$An impressionistic, whole-before-parts narrative told with deliberate dramatic staging (materials, demonstrations, a teacher's own prepared telling) that gives children a complete "big picture" before any single discipline is studied in isolation — structurally the same move as a Structure of Knowledge Diagram's Facts→Concepts→Principles hierarchy, but delivered as narrative rather than diagram.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-great-story","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["montessori-pedagogy"],"examples":["The First Great Lesson's dramatic demonstration of the formation of the universe, told before any single unit on astronomy, chemistry, or geography begins."],"nonExamples":[],"relations":{"skos:related":["OE-CONCEPT-cosmic-k12-interconnectedness"]},"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('cab10790-5d51-5768-a567-df0ec9aca67d', v_en, 'concept', $J$Fundamental Human Needs$J$, $J$Montessori pedagogy: Montessori's Third Great Lesson framework: physical needs (food, shelter, defense, transportation) and spiritual/ psychological needs (art, religion, music, a sense of significance) that every known human group has met, in different ways, across every period of history and every culture — the organizing device for Cosmic Education's treatment of cultural diversity.

Evolutionary anthropology: A close structural counterpart to evolutionary anthropology's own treatment of universal human needs met through variable cultural means — directly comparable to the cross-cultural, multiply-realized-solutions framing eva_buch (Hanisch, forthcoming) develops for Sozialkunde/Ethik curricula, though neither source cites the other; the parallel is this LPM's own synthesis, not an existing claim in either source.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-fundamental-human-needs","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["montessori-pedagogy","evolutionary-anthropology"],"examples":["Shelter met by an igloo, a yurt, a longhouse, or an apartment block — one need, many culturally variable solutions."],"nonExamples":[],"relations":{"skos:related":["OE-CONCEPT-oe-interdisciplinary-culture","OE-CONCEPT-cosmic-k12-cultural-diversity-of-solutions"]},"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('ee309c9b-3f26-5573-a234-c8ba4f724ea2', v_en, 'concept', $J$Cultural Diversity of Solutions$J$, $J$The pattern by which one shared human need or problem is met by many genuinely different, equally legitimate cultural solutions, none of which is the single "correct" answer.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-cultural-diversity-of-solutions","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["general"],"examples":[],"nonExamples":[],"relations":{"skos:broader":["OE-CONCEPT-cosmic-k12-fundamental-human-needs"],"skos:related":["OE-CONCEPT-oe-interdisciplinary-culture","OE-CONCEPT-oe-interdisciplinary-innovation"]},"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('4e4b1e48-27e3-549a-8137-97434dc3dfb5', v_en, 'concept', $J$Going Out$J$, $J$Montessori elementary pedagogy's term for a self-directed research expedition — a library visit, an expert interview, a field trip — that a child or small group initiates in response to a question a Great Lesson raised, planned and carried out largely by the children themselves rather than assigned top-down. The named mechanism by which an impressionistic Great Story becomes detailed, self-motivated disciplinary study.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-going-out","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["montessori-pedagogy"],"examples":["A small group who became curious about volcanoes during the First Great Lesson arranges its own library research and report, unprompted by the teacher's own lesson plan."],"nonExamples":[],"relations":{"skos:related":["OE-CONCEPT-cosmic-k12-great-story","OE-CONCEPT-oe-interdisciplinary-agency"]},"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('2644f7c1-7b57-5502-aef3-4ac2721e8887', v_en, 'concept', $J$Timeline Reasoning$J$, $J$Using a physical or represented timeline (Montessori's own Timeline of Life and Clock of Eras among the named materials) as a cognitive tool for representing scale, sequence, and duration across time spans far longer than direct experience — a specific, teachable skill distinct from simply knowing dated facts, and one with a real, independently developed international research base (learning-progression literature on "big ideas," OER Project's Big History Project units on scale and thresholds of complexity).$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-timeline-reasoning","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["general"],"examples":["Placing a paper timeline of one's own life, a grandparent's life, and human history on the same wall to compare their very different scales."],"nonExamples":[],"relations":{"skos:related":["OE-CONCEPT-cosmic-k12-great-story"]},"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('ccda801f-c777-50be-9005-97b2b7637286', v_en, 'concept', $J$Gratitude and Wonder$J$, $J$The affective/dispositional response Montessori explicitly intended Cosmic Education to cultivate alongside its factual content — an emotional and ethical orientation toward the scale and interdependence the Great Lessons reveal, not a side effect of teaching it but a named goal in its own right.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-gratitude-and-wonder","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["montessori-pedagogy"],"examples":[],"nonExamples":[],"relations":{"skos:related":["OE-CONCEPT-cosmic-k12-cosmic-task","OE-CONCEPT-cosmic-k12-interconnectedness"]},"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('4169768d-db96-5f05-a337-668ed11d0a0f', v_en, 'concept', $J$Sign and Symbol$J$, $J$The core idea of the Fourth Great Lesson (the Story of Language/Communication in Signs): that an arbitrary mark or sound can stand for something else by shared agreement, and that this single invention — not any one alphabet or language — is what let human knowledge accumulate and transmit across generations beyond what memory alone could carry.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-sign-and-symbol","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["general"],"examples":[],"nonExamples":[],"relations":{"skos:related":["OE-CONCEPT-oe-interdisciplinary-communication","OE-CONCEPT-oe-interdisciplinary-transmission"]},"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('20cfab66-d5e7-5b8d-a628-e09a6f6d77f2', v_en, 'concept', $J$Quantity and Symbol$J$, $J$The core idea of the Fifth Great Lesson (the Story of Numbers/Mathematics): that quantity itself is an abstraction humans learned to represent with symbols, that this representational leap (tallies, place value, zero) is itself a historical human achievement rather than a fact of nature, and that mathematics is therefore itself one of the Great Stories, not a separate, story-free subject.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-quantity-and-symbol","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["general"],"examples":[],"nonExamples":[],"relations":{"skos:related":["OE-CONCEPT-cosmic-k12-sign-and-symbol","OE-CONCEPT-oe-interdisciplinary-innovation"]},"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('fa0cdab9-589f-5c48-86b6-98425b16b360', v_en, 'concept', $J$Evolutionary Process$J$, $J$Any process by which variants are generated, selected, and transmitted across iterations within a system — applicable to genetic, cultural, technological, or cognitive systems alike.$J$, NULL, $J${"conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-evolutionary-process","source_vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","origin":"conceptbase-import","definition_language":"en","note":"Imported by id from ConceptBase; wording is ConceptBase's."}$J$::jsonb, $J$accepted$J$),
  ('084ebf42-2ed1-5cea-9b33-4b4ff50e717c', v_en, 'concept', $J$Culture$J$, $J$Socially transmitted knowledge, beliefs, practices, and artifacts shared within a group, persisting beyond any single individual.$J$, NULL, $J${"conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-culture","source_vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","origin":"conceptbase-import","definition_language":"en","note":"Imported by id from ConceptBase; wording is ConceptBase's."}$J$::jsonb, $J$accepted$J$),
  ('5d385012-4917-5192-beeb-13cbf2883b65', v_en, 'concept', $J$Transmission$J$, $J$The process by which information, traits, or practices move from one holder (organism, person, group, or system) to another.$J$, NULL, $J${"conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-transmission","source_vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","origin":"conceptbase-import","definition_language":"en","note":"Imported by id from ConceptBase; wording is ConceptBase's."}$J$::jsonb, $J$accepted$J$),
  ('18bb9cdf-476d-5a87-abdd-44cc68b4a712', v_en, 'concept', $J$Innovation$J$, $J$The generation of a novel variant — an idea, practice, technology, or trait — that did not previously exist within a system.$J$, NULL, $J${"conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-innovation","source_vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","origin":"conceptbase-import","definition_language":"en","note":"Imported by id from ConceptBase; wording is ConceptBase's."}$J$::jsonb, $J$accepted$J$)
