  -- ====================================================================
  -- Cosmic Education LPM (Deutsch)
  -- ====================================================================
  VALUES (v_de, 'cosmic-education-lpm-de', $J$Cosmic Education LPM (Deutsch)$J$, $J$Der deutsche Raum des Cosmic-Education-LPM: fünf Stränge, je einer pro Große Erzählung (Universum, Leben, Mensch, Sprache, Zahlen), jeweils über sieben Altersbänder von früher Kindheit bis Oberstufe. Montessoris eigener Geltungsbereich sind die Altersstufen 6 bis 12 (Bänder GB-1 bis GB-3); die übrigen Bänder sind ein informeller Vorläufer und Übergaben an andere Modelle. Zuordnungen zu den Grundschullehrplänen von Sachsen, Sachsen-Anhalt und Thüringen, zum GDSU-Perspektivrahmen, zu Montessoris eigener Tradition, zum IB PYP und zum Big History Project hängen an den einzelnen Stufen.$J$, 'active', 'in-development',
    $J$Von Menschen kuratiert (Ziel); wird in OpenLPM geprüft und weiterentwickelt. Am 07.11.2026 aus dem Entwurf cosmic-education-k12 übernommen. Keine Fachperson hat den Inhalt geprüft. Die deutschen Indikatoren und Begriffsdefinitionen sind ein Entwurf von Claude.$J$,
    'hosted', TRUE, 'draft', v_parent, 'thematic', '{}'::TEXT[], ARRAY['montessori','cosmic-education','interdisciplinary']::TEXT[], ARRAY['de']::TEXT[])
  ON CONFLICT (slug) DO NOTHING;


  SELECT v_de, $J$cosmic-education-k12 (draft folder, moved into this space)$J$, $J$YAML (ConceptBase oe:LPM / oe:Strand shape)$J$, $J$CC-BY-NC-SA-4.0 (the draft's own LICENSE). Structurally imported by this migration.$J$, NULL
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_de AND source_name = $J$cosmic-education-k12 (draft folder, moved into this space)$J$);
  SELECT v_de, $J$Crosswalk: OER Project — Big History Project (Acht Schwellen)$J$, $J$Crosswalk table (state-standards)$J$, $J$Das Big History Project des OER Project ordnet 13,8 Milliarden Jahre Geschichte um acht „Schwellen zunehmender Komplexität“ — bestätigt: der Urknall; Sterne leuchten auf; neue chemische Elemente; Erde und Sonnensystem; Leben auf der Erde; kollektives Lernen; Landwirtschaft; die moderne Revolution.$J$, NULL
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_de AND source_name = $J$Crosswalk: OER Project — Big History Project (Acht Schwellen)$J$);
  SELECT v_de, $J$Crosswalk: Perspektivrahmen Sachunterricht (GDSU)$J$, $J$Crosswalk table (national-framework)$J$, $J$Die Gesellschaft für Didaktik des Sachunterrichts (GDSU) veröffentlicht den Perspektivrahmen Sachunterricht (2002, vollständig überarbeitet 2013; eine weitere Überarbeitung ist laut Literaturverzeichnis des GDSU-Journals „i.V.“). Die fünf zugrunde liegenden Perspektiven wurden in dieser Sitzung NICHT direkt aus dem Perspektivrahmen-Dokument selbst bestätigt, sondern aus der bestätigten Struktur des sachsen-anhaltischen Fachlehrplans abgeleitet.$J$, NULL
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_de AND source_name = $J$Crosswalk: Perspektivrahmen Sachunterricht (GDSU)$J$);
  SELECT v_de, $J$Crosswalk: IB Primary Years Programme — Sechs transdisziplinäre Themen$J$, $J$Crosswalk table (state-standards)$J$, $J$Das Primary Years Programme (PYP) des International Baccalaureate ordnet sein gesamtes Curriculum um sechs transdisziplinäre Themen. Eine überarbeitete Fassung der Themenbeschreibungen wurde als real und aktuell bestätigt (Schulen können sie bereits übernehmen, verpflichtend für alle PYP-Schulen ab September 2027).$J$, NULL
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_de AND source_name = $J$Crosswalk: IB Primary Years Programme — Sechs transdisziplinäre Themen$J$);
  SELECT v_de, $J$Crosswalk: Montessori Kosmische Erziehung (eigene Tradition)$J$, $J$Crosswalk table (pedagogical-tradition)$J$, $J$Die eigene Primärquelle dieses Modells, kein gewöhnlicher sekundärer Abgleich — dennoch als formaler Abgleich aufgenommen, damit die App-Funktion „Lehrplan-Abgleich“ zeigt, wie weit eine tatsächlich Montessori-Materialien einsetzende Schule mit der eigenen Strang-/Stufenstruktur dieses Modells übereinstimmt.$J$, NULL
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_de AND source_name = $J$Crosswalk: Montessori Kosmische Erziehung (eigene Tradition)$J$);
  SELECT v_de, $J$Crosswalk: Fachlehrplan Grundschule Sachunterricht (Sachsen-Anhalt)$J$, $J$Crosswalk table (state-standards)$J$, $J$Direkt aus dem offiziellen PDF des LISA (Landesinstitut für Schulqualität und Lehrerbildung Sachsen-Anhalt), Stand 01.08.2019, entnommen und ausgewertet am 11.09.2026: die 3 prozessbezogenen Kompetenzen (Erkunden; Kommunizieren und Argumentieren; Präsentieren) sowie die 5 inhaltsbezogenen Kompetenzbereiche.$J$, NULL
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_de AND source_name = $J$Crosswalk: Fachlehrplan Grundschule Sachunterricht (Sachsen-Anhalt)$J$);
  SELECT v_de, $J$Crosswalk: Sächsischer Lehrplan Grundschule Sachunterricht$J$, $J$Crosswalk table (state-standards)$J$, $J$Direkt aus der Lehrplan-Datenbank des Sächsischen Schulportals (schulportal.sachsen.de/lplandb/lehrplan/80) entnommen, abgerufen am 11.09.2026: die sechs Lernbereiche mit Stundenzahlen für die Klassenstufen 1/2, 3 und 4, sowie die benannten Wahlbereiche jeder Klassenstufe.$J$, $J$https://schulportal.sachsen.de/lplandb/lehrplan/80$J$
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_de AND source_name = $J$Crosswalk: Sächsischer Lehrplan Grundschule Sachunterricht$J$);
  SELECT v_de, $J$Crosswalk: Thüringer Lehrplan Heimat- und Sachkunde$J$, $J$Crosswalk table (state-standards)$J$, $J$TEILWEISE GESICHERT, ehrlich gekennzeichnet statt aufgefüllt: das Thüringer Schulportal bestätigt drei Lernbereiche — Natur und Technik; Raum und Zeit; Lebewesen und Lebensräume — aus zwei unabhängigen Suchtreffern dieser Sitzung, doch die Quell-PDF konnte in dieser Sitzung nicht ausgelesen werden. Jede Zuordnung unten gilt daher als unsicher.$J$, NULL
  WHERE NOT EXISTS (SELECT 1 FROM project_source_declarations WHERE project_id = v_de AND source_name = $J$Crosswalk: Thüringer Lehrplan Heimat- und Sachkunde$J$);

  IF v_user IS NOT NULL THEN
    UPDATE projects SET created_by = v_user WHERE id = v_de AND created_by IS NULL;
  END IF;


Vorbehalt aus der Evolutionsbiologie: Wörtlich als Ursachenbehauptung gelesen („die Streifen einer Biene gibt es, weil das Ökosystem Bestäuber braucht“), ist das Zwecksetzung durch Absicht oder Plan (Design-Teleologie). Die Evolutionsdidaktik behandelt dieses Erklärungsmuster als hartnäckiges, gut belegtes Fehlkonzept (Kelemen und Rosset 2009 zu zweckgerichteten Erklärungen bei Erwachsenen). Die in diesem Ökosystem festgehaltene Position (theorybase:OE-PROPOSITION-selection-teleology-legitimate) lautet: Zweckgerichtete Sprache ist vertretbar, wenn sie der Selektions-Teleologie folgt (ein Merkmal bleibt erhalten, WEIL seine Wirkungen über Generationen hinweg unterschiedliches Überleben und Fortpflanzen bewirkten). Sie ist nicht vertretbar, wenn sie der Design-Teleologie folgt (ein Merkmal existiert, WEIL etwas es brauchte oder beabsichtigte). Ob Montessoris Rahmung der Kosmischen Aufgabe im realen Unterricht bei Kindern die eine oder die andere Art des Denkens hervorbringt, ist eine offene, noch nicht untersuchte empirische Frage. Sie ist die zentrale Forschungschance dieses Modells und kein Mangel, den man stillschweigend umgehen sollte.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-cosmic-task","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["montessori-pedagogy","evolutionary-biology-caveat"],"examples":["Regenwürmer durchlüften den Boden, das hilft den Pflanzen beim Wachsen, die Tiere ernähren, welche Nährstoffe wieder an den Boden zurückgeben.","Ein Kind soll seine eigene „Aufgabe“ in der Familie oder Klasse benennen, als gefühlsnaher, kindgerechter Einstieg, bevor irgendeine biologische Behauptung gemacht wird."],"nonExamples":["Ein Merkmal existiert, weil die Art es zum Überleben braucht (Design-Teleologie und nicht Selektions-Teleologie; genau diesen Unterschied soll der Begriff sichtbar machen und nicht übergehen)."],"relations":{"skos:related":["OE-CONCEPT-cosmic-k12-interconnectedness","OE-CONCEPT-oe-interdisciplinary-evolutionary-process"]},"review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('bd996347-5cb0-54c9-a9cc-dc9f5347d7d0', v_de, 'concept', $J$Vernetztheit$J$, $J$Die Idee, die für die Kosmische Erziehung zentral ist und unabhängig davon auch für die deutsche Sachunterrichtsdidaktik (Vielperspektivität und Vernetzung, Peschel, Goll & Schomaker 2026, GDSU Journal Heft 16): Kein einzelnes Phänomen wird aus nur einer Fachperspektive vollständig verstanden. Ein vollständiges Bild entsteht, wenn mehrere Perspektiven aktiv aufeinander bezogen und nicht bloß nebeneinandergestellt werden.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-interconnectedness","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["general"],"examples":["Ein Fluss verbindet Geologie (wohin das Wasser fließt), Biologie (was darin lebt), Geschichte (warum eine Stadt an ihm gebaut wurde) und Wirtschaft (wie er heute genutzt wird)."],"nonExamples":[],"relations":{"skos:broader":["OE-CONCEPT-cosmic-k12-cosmic-task"],"skos:related":["OE-CONCEPT-oe-interdisciplinary-evolutionary-process"]},"review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('a1d96e1e-fcc7-5991-96d2-46fed5d7ba42', v_de, 'concept', $J$Große Erzählung$J$, $J$Eine eindrucksvolle Erzählung, die vom Ganzen zu den Teilen geht und bewusst dramatisch inszeniert wird (Materialien, Vorführungen, die vorbereitete Erzählung der Lehrkraft). Sie gibt Kindern ein vollständiges „großes Bild“, bevor ein einzelnes Fach für sich studiert wird. Strukturell ist das derselbe Schritt wie die Hierarchie Fakten, Konzepte, Prinzipien im Wissensstruktur-Diagramm, nur als Erzählung und nicht als Diagramm vermittelt.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-great-story","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["montessori-pedagogy"],"examples":["Die dramatische Vorführung der Ersten Großen Erzählung zur Entstehung des Universums, erzählt bevor irgendeine Einheit zu Astronomie, Chemie oder Geographie beginnt."],"nonExamples":[],"relations":{"skos:related":["OE-CONCEPT-cosmic-k12-interconnectedness"]},"review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('db706eef-d166-5f71-a2e8-58a5486eff3a', v_de, 'concept', $J$Grundbedürfnisse des Menschen$J$, $J$Aus Montessoris Pädagogik: Das Rahmenwerk der Dritten Großen Erzählung. Es unterscheidet körperliche Bedürfnisse (Nahrung, Unterkunft, Verteidigung, Fortbewegung) und seelische Bedürfnisse (Kunst, Religion, Musik, ein Gefühl von Bedeutung), die jede bekannte Menschengruppe in jeder Epoche und Kultur auf unterschiedliche Weise erfüllt hat. Es ist das Ordnungsprinzip der Kosmischen Erziehung für den Umgang mit kultureller Vielfalt.

Aus der evolutionären Anthropologie: Ein enges strukturelles Gegenstück zur Sicht der evolutionären Anthropologie auf allgemeine menschliche Bedürfnisse, die durch variable kulturelle Mittel erfüllt werden. Es ist unmittelbar vergleichbar mit der kulturübergreifenden Sicht mehrfach verwirklichter Lösungen, die eva_buch (Hanisch, erscheint) für Sozialkunde- und Ethik-Lehrpläne entwickelt. Keine der beiden Quellen zitiert die andere. Die Parallele ist die eigene Synthese dieses Modells und keine bestehende Aussage in einer der Quellen.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-fundamental-human-needs","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["montessori-pedagogy","evolutionary-anthropology"],"examples":["Unterkunft, erfüllt durch Iglu, Jurte, Langhaus oder Mehrfamilienhaus: ein Bedürfnis, viele kulturell verschiedene Lösungen."],"nonExamples":[],"relations":{"skos:related":["OE-CONCEPT-oe-interdisciplinary-culture","OE-CONCEPT-cosmic-k12-cultural-diversity-of-solutions"]},"review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('cb4de8ef-e134-5d40-bf18-168111e1fb10', v_de, 'concept', $J$Kulturelle Vielfalt der Lösungen$J$, $J$Das Muster, nach dem ein gemeinsames menschliches Bedürfnis oder Problem durch viele wirklich verschiedene, gleichermaßen berechtigte kulturelle Lösungen erfüllt wird, von denen keine die einzig „richtige“ ist.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-cultural-diversity-of-solutions","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["general"],"examples":[],"nonExamples":[],"relations":{"skos:broader":["OE-CONCEPT-cosmic-k12-fundamental-human-needs"],"skos:related":["OE-CONCEPT-oe-interdisciplinary-culture","OE-CONCEPT-oe-interdisciplinary-innovation"]},"review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('30b747d8-c2ba-58bd-9190-c48f860e803f', v_de, 'concept', $J$Erkundungsgang$J$, $J$Aus Montessoris Pädagogik: Der Begriff der Montessori-Elementarpädagogik für eine selbstgesteuerte Erkundungsreise, etwa ein Bibliotheksbesuch, ein Expertengespräch oder ein Ausflug, die ein Kind oder eine kleine Gruppe aufgrund einer Frage beginnt, die eine Große Erzählung aufgeworfen hat. Geplant und durchgeführt wird sie weitgehend von den Kindern selbst und nicht von oben zugewiesen. Es ist der benannte Mechanismus, durch den aus einer eindrucksvollen Großen Erzählung ein detailliertes, selbst motiviertes Fachstudium wird.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-going-out","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["montessori-pedagogy"],"examples":["Eine kleine Gruppe, die in der Ersten Großen Erzählung neugierig auf Vulkane wurde, organisiert ohne Anstoß aus dem Stundenplan der Lehrkraft eigene Bibliotheksrecherche und Bericht."],"nonExamples":[],"relations":{"skos:related":["OE-CONCEPT-cosmic-k12-great-story","OE-CONCEPT-oe-interdisciplinary-agency"]},"review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('1c5635d7-1aad-5323-be9d-f9ee8129f283', v_de, 'concept', $J$Zeitleisten-Denken$J$, $J$Eine physische oder dargestellte Zeitleiste (Montessoris Zeitleiste des Lebens und Erdzeituhr gehören zu den benannten Materialien) als Denkwerkzeug nutzen, um Größenordnung, Reihenfolge und Dauer über Zeitspannen darzustellen, die weit länger sind als die unmittelbare Erfahrung. Das ist eine eigene, lehrbare Fähigkeit, verschieden vom bloßen Kennen datierter Fakten, und sie hat eine unabhängig entwickelte internationale Forschungsbasis (Lernprogressionsforschung zu „Big Ideas“, die Einheiten des Big History Project des OER Project zu Maßstab und Schwellen der Komplexität).$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-timeline-reasoning","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["general"],"examples":["Eine Papierzeitleiste des eigenen Lebens, des Lebens einer Großmutter und der Menschheitsgeschichte an dieselbe Wand hängen, um ihre sehr verschiedenen Größenordnungen zu vergleichen."],"nonExamples":[],"relations":{"skos:related":["OE-CONCEPT-cosmic-k12-great-story"]},"review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('988212dc-893a-5d38-b6e7-c082c4399c48', v_de, 'concept', $J$Dankbarkeit und Staunen$J$, $J$Aus Montessoris Pädagogik: Die gefühlsmäßige, haltungsbezogene Antwort, die Montessori mit der Kosmischen Erziehung ausdrücklich neben dem Sachinhalt fördern wollte. Es ist eine emotionale und ethische Ausrichtung auf die Größe und gegenseitige Abhängigkeit, die die Großen Erzählungen zeigen. Sie ist kein Nebeneffekt des Unterrichts, sondern ein benanntes eigenes Ziel.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-gratitude-and-wonder","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["montessori-pedagogy"],"examples":[],"nonExamples":[],"relations":{"skos:related":["OE-CONCEPT-cosmic-k12-cosmic-task","OE-CONCEPT-cosmic-k12-interconnectedness"]},"review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('3bc03b9d-5f9d-591c-95e5-7ad870118b88', v_de, 'concept', $J$Zeichen und Symbol$J$, $J$Der Kerngedanke der Vierten Großen Erzählung (Geschichte der Sprache, Kommunikation in Zeichen): Ein beliebiges Zeichen oder ein Laut kann durch gemeinsame Vereinbarung für etwas anderes stehen. Diese eine Erfindung, und nicht ein einzelnes Alphabet oder eine einzelne Sprache, hat es möglich gemacht, dass sich menschliches Wissen ansammeln und über Generationen weitergeben lässt, weit über das hinaus, was das Gedächtnis allein tragen könnte.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-sign-and-symbol","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["general"],"examples":[],"nonExamples":[],"relations":{"skos:related":["OE-CONCEPT-oe-interdisciplinary-communication","OE-CONCEPT-oe-interdisciplinary-transmission"]},"review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
  ('be63cb60-5a7b-52e2-bcdc-ce85dcd976a7', v_de, 'concept', $J$Menge und Symbol$J$, $J$Der Kerngedanke der Fünften Großen Erzählung (Geschichte der Zahlen und der Mathematik): Menge selbst ist eine Abstraktion, die Menschen mit Zeichen darstellen lernten. Dieser Schritt der Darstellung (Strichliste, Stellenwert, Null) ist selbst eine historische menschliche Leistung und keine Tatsache der Natur. Mathematik ist deshalb selbst eine der Großen Erzählungen und kein davon getrenntes, erzählungsfreies Fach.$J$, NULL, $J${"source_id":"OE-CONCEPT-cosmic-k12-quantity-and-symbol","vocabulary":"COSMIC-K12-v0.1.0","origin":"local-to-cosmic-education","definition_parts":["general"],"examples":[],"nonExamples":[],"relations":{"skos:related":["OE-CONCEPT-cosmic-k12-sign-and-symbol","OE-CONCEPT-oe-interdisciplinary-innovation"]},"review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/vocabulary/COSMIC-K12-v0.1.0.yaml"}}$J$::jsonb, $J$proposed$J$),
