  INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status) VALUES
  ('77cc800e-5b91-588c-b9e8-343e50435021', v_en, 'concept', $J$Cosmic Task$J$, $J$Montessori pedagogy: Montessori's own claim that every element, organism, and force plays a role that serves the maintenance of the whole living and physical world — the affective and ethical core of Cosmic Education, used pedagogically to build a child's sense of purpose and responsibility within a larger system.
  INSERT INTO lpm_data_objects (id, project_id, object_type, title, description, grade_band, subject_area, content, status) VALUES
  ('074fb752-1a29-5b07-9ab2-b18240805a02', v_en, $J$strand$J$, $J$The Story of the Universe$J$, $J$Montessori's First Great Lesson: the formation of the universe, the solar system, and Earth, told as one dramatic impressionistic narrative — matter, energy, gravity, and the laws that govern them, presented as a "big picture" before any single science subject (astronomy, chemistry, physics, geography) is studied in isolation. The throughline concept (Interconnectedness — everything in the physical universe operates by shared, discoverable laws) is introduced narratively in Lower Elementary and deepens into real Earth-science and physical-science content as children's own "Going Out" research follows their questions outward from the story.$J$, NULL, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe","sequence":1,"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands; Montessori's own claimed scope is GB-1–GB-3, ~ages 6–12)","associatedDomains":["Science","Geography","Chemistry","Physics"],"relations":{"foundationalTo":["OE-STRAND-cosmic-education-k12-story-of-life"],"parallel":[]},"homeAnchors":[{"id":"computer-models","label":"Computer Models","description":"Simplified rule-based simulations used to reproduce and reason about complex real systems."},{"id":"our-mind","label":"Our Mind","description":"Turning the tools of causal reasoning onto our own thinking, feeling, and behavior."}],"thinkingTool":{"id":"structure-of-knowledge-diagrams","label":"Structure of Knowledge Diagrams","description":"A Facts → Concepts → Principles hierarchy that shows how many specific details connect to one bigger idea — the same relationship a Great Lesson has to the detailed disciplinary studies that branch off it."},"essentialQuestion":{"broad":"Where did everything come from, and why does it hold together?","worked":"A single story can hold astronomy, chemistry, geography, and physics together without flattening any of them — what does a class lose, and what does it gain, by starting from one big story instead of four separate subjects?"},"ecosystemConnections":[{"id":"universe-to-big-history","repo":"Big History Project (OER Project, external)","kind":"continues-into","title":"Continues into: Big History Project's Thresholds 1–4","description":"Strand 1 stops at approximately age 12, per Montessori's own claimed scope. The OER Project's free, secondary-level Big History Project picks up the identical universe/solar-system/Earth narrative at exactly that age, covering the Big Bang, Stars Light Up, New Chemical Elements, and Earth and the Solar System as its own first four 'Thresholds of increasing complexity.'"},{"id":"whole-lpm-to-halle-memo","repo":"deutsche_lp","kind":"continues-into","title":"Operationalizes: the Halle collaboration research memo","description":"This entire LPM is the concrete, running first step the 2026-09-11 research-synthesis memo (deutsche_lp/docs/strategy/2026-09-11-halle-montessori-cosmic-education-collaboration.md) recommended: a real Cosmic Education LPM skeleton, built to offer directly to a cooperation partner's doctoral research, not just proposed."}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('f1ae0609-9dd8-5bc6-a1fe-2791cb04b8a0', v_en, $J$substrand$J$, $J$Wondering About the Sky$J$, NULL, $J$GB-0$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb0","typicalGradeBand":"GB-0 (~3–6)","gradeBandId":"GB-0","gradeBandLabel":"Early Childhood","approxAge":"3–6","required":false,"concepts":[],"montessoriScope":"informal-precursor","crosswalks":[{"system":"sachsen-lehrplan","systemName":"Saxony Primary Curriculum (Lehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"vor der Schulpflicht","note":"Kita falls before compulsory schooling and outside the Sachsen Lehrplan's scope entirely — this LPM's own GB-0 band is likewise an informal, non-Montessori-sourced precursor, so the two align in having no formal content here, not by coincidence.","noteLanguage":"en","confidence":"confirmed","concepts":[],"appliesToAllStrands":true}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('6be77c3b-e9cc-51fe-9ed2-951fadf8e883', v_en, $J$performance_indicator$J$, $J$The Universe · GB-0.1$J$, $J$Notices and asks questions about the sun, moon, and stars through direct sensory experience (day/night walks, simple sky observation), with no formal content expectation — an informal precursor this repo adds, not part of Montessori's own First Great Lesson.$J$, $J$GB-0$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb0#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('33938aeb-05ca-5619-8329-ca35dec2f57d', v_en, $J$substrand$J$, $J$The Great Story, First Telling$J$, $J$Key concepts: Great Story, Interconnectedness, Gratitude and Wonder$J$, $J$GB-1$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb1","typicalGradeBand":"GB-1 (~6–8)","gradeBandId":"GB-1","gradeBandLabel":"Primary I","approxAge":"6–8","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-great-story","emphasis":"primary"},{"id":"OE-CONCEPT-cosmic-k12-interconnectedness","emphasis":"primary"},{"id":"OE-CONCEPT-cosmic-k12-gratitude-and-wonder","emphasis":"reinforcing"}],"montessoriScope":"inside","crosswalks":[{"system":"gdsu-perspektivrahmen","systemName":"GDSU Perspektivrahmen Sachunterricht (national didactic framework)","systemType":"national-framework","code":"Naturwissenschaftliche Perspektive","note":"Inferred perspective name (see sourceNote) — the natural-science perspective is the clearest single-perspective home for Strand 1, though the framework's own point (Vielperspektivität und Vernetzung) is that no strand should stay inside one perspective alone.","noteLanguage":"en","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-interconnectedness"],"appliesToAllStrands":false},{"system":"ib-pyp","systemName":"IB Primary Years Programme — Six Transdisciplinary Themes","systemType":"state-standards","code":"How the World Works","note":"Confirmed theme name — the PYP's own closest match to Strand 1's physical-universe content; the 2025 revision's broadened natural-world framing (per the source's own description) makes this an even closer match than the theme's pre-revision human-systems-only framing would have been.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-great-story"],"appliesToAllStrands":false},{"system":"montessori-tradition","systemName":"Montessori Cosmic Education (native tradition)","systemType":"pedagogical-tradition","code":"First Great Lesson: 'The Coming of the Universe and the Earth' (dramatic telling)","note":"The named Great Lesson itself — a scripted, materials-supported dramatic demonstration, per the Global Montessori Network's own published elementary resource and widely-documented AMI/AMS elementary practice.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-great-story","OE-CONCEPT-cosmic-k12-gratitude-and-wonder"],"appliesToAllStrands":false},{"system":"sachsen-anhalt-lehrplan","systemName":"Saxony-Anhalt Primary Curriculum (Fachlehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"Naturwissenschaftlicher Bereich, Schuljahrgang 2: 'Luft – Feuer – Wasser – Boden'","note":"The Sachsen-Anhalt Lehrplan's own first-listed Naturwissenschaftlicher-Bereich unit (Air-Fire-Water-Earth as conditions for life) is a direct, confirmed match for Strand 1's earliest content — the source text itself frames these four elements as foundational to life, structurally close to a Great-Lesson-style 'big picture first' move.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-interconnectedness"],"appliesToAllStrands":false},{"system":"sachsen-lehrplan","systemName":"Saxony Primary Curriculum (Lehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"LB 5: Begegnung mit Raum und Zeit (26 Ustd., Kl. 1/2)","note":"Klassenstufe 1/2's Lernbereich 5 ('Encounter with Space and Time') is the closest structural match to a first, impressionistic telling of the Great Lessons — both concern orienting a young child in time and space before detailed disciplinary study begins.","noteLanguage":"en","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-great-story","OE-CONCEPT-cosmic-k12-interconnectedness"],"appliesToAllStrands":false},{"system":"thueringen-lehrplan","systemName":"Thuringia Primary Curriculum (Lehrplan Heimat- und Sachkunde)","systemType":"state-standards","code":"Lernbereich: Raum und Zeit","note":"The Thüringer Lehrplan's own 'Raum und Zeit' (Space and Time) Lernbereich name is a strong plausible match for Strand 1's early content by name alone — the same reasoning applied to Sachsen's identically-named Lernbereich 5 above — but no Klassenstufe-level detail is confirmed.","noteLanguage":"en","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-great-story"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('0129160b-d425-5cef-a442-b24cbb50016a', v_en, $J$performance_indicator$J$, $J$The Universe · GB-1.1$J$, $J$Listens to and can retell, in their own words and without requiring technical vocabulary, the dramatic account of how the universe, solar system, and Earth formed.$J$, $J$GB-1$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb1#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('1cee0d1d-22ff-5d5a-9b6b-d41202baa138', v_en, $J$performance_indicator$J$, $J$The Universe · GB-1.2$J$, $J$Names at least one law or force (e.g. gravity, or matter's tendency to organize) that the story says applies everywhere in the universe, not just on Earth.$J$, $J$GB-1$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb1#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('f90857d7-4fb3-506e-8165-c63aea6cf0e2', v_en, $J$performance_indicator$J$, $J$The Universe · GB-1.3$J$, $J$Expresses, in their own words or through a chosen creative medium, a felt response (wonder, gratitude, curiosity) to the scale of the story — the Noticing Tool applied to one's own reaction, not just the content.$J$, $J$GB-1$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb1#pi3","ordinal":3,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('f25c1b1f-311f-5d8d-a62d-842091dd4692', v_en, $J$substrand$J$, $J$Following the Story Outward: Earth Science$J$, $J$Key concepts: Going Out, Interconnectedness$J$, $J$GB-2$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb2","typicalGradeBand":"GB-2 (~8–10)","gradeBandId":"GB-2","gradeBandLabel":"Primary II","approxAge":"8–10","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-going-out","emphasis":"primary"},{"id":"OE-CONCEPT-cosmic-k12-interconnectedness","emphasis":"reinforcing"}],"montessoriScope":"inside","crosswalks":[{"system":"gdsu-perspektivrahmen","systemName":"GDSU Perspektivrahmen Sachunterricht (national didactic framework)","systemType":"national-framework","code":"PVT: Nachhaltigkeitsthemen (Klimawandel) — perspective-linking, not single-perspective","note":"Confirmed as a real, current PVT (perspective-linking topic area) — Strand 1's Earth-science content, taught as a genuinely perspective-linking topic rather than pure natural science alone, is a direct fit for exactly the kind of Vernetzung (networking) the GDSU Journal's own 2026 lead article argues Sachunterricht must achieve, not just aspire to.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-interconnectedness","OE-CONCEPT-cosmic-k12-going-out"],"appliesToAllStrands":false},{"system":"montessori-tradition","systemName":"Montessori Cosmic Education (native tradition)","systemType":"pedagogical-tradition","code":"Follow-up 'Going Out' research + Earth-science charts (God With No Hands materials)","note":"Confirmed named materials (per multiple independent Montessori-practitioner sources): free charts and 'God With No Hands' follow-up work extending the First Great Lesson into concrete Earth-science study.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-going-out"],"appliesToAllStrands":false},{"system":"sachsen-anhalt-lehrplan","systemName":"Saxony-Anhalt Primary Curriculum (Fachlehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"Naturwissenschaftlicher Bereich, Schuljahrgang 4: 'Wetter und Jahreszeiten'","note":"Weather-and-seasons content at end-of-Schuljahrgang-4 explicitly includes 'Tagbogen der Sonne im Sommer und Winter, Daten der Winter- und Sommersonnenwende' (the sun's daily arc, solstice dates) — real, confirmed astronomical content that directly continues Strand 1's Great Story.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-timeline-reasoning","OE-CONCEPT-cosmic-k12-going-out"],"appliesToAllStrands":false},{"system":"sachsen-lehrplan","systemName":"Saxony Primary Curriculum (Lehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"LB 4: Begegnung mit Phänomenen der unbelebten Natur (12 Ustd., Kl. 3); LB 5: Begegnung mit Raum und Zeit (14 Ustd., Kl. 3)","note":"Klassenstufe 3's phenomena-of-inanimate-nature and space/time Lernbereiche together give real room for Strand 1's Earth-science 'Going Out' follow-up content.","noteLanguage":"en","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-going-out","OE-CONCEPT-cosmic-k12-interconnectedness"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('604417ee-528d-5139-83fd-518f3660f50a', v_en, $J$performance_indicator$J$, $J$The Universe · GB-2.1$J$, $J$Plans and carries out a self-directed research follow-up (a 'Going Out') on one question the Great Story raised — e.g. volcanoes, the water cycle, or the formation of a specific rock type — largely self-initiated rather than assigned.$J$, $J$GB-2$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb2#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('4480c659-873b-5698-baaf-5fcad1ab1b48', v_en, $J$performance_indicator$J$, $J$The Universe · GB-2.2$J$, $J$Describes at least three states or forms matter takes (solid, liquid, gas; or specific rock/mineral types) as concrete evidence for the story's claim that matter organizes according to shared rules.$J$, $J$GB-2$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb2#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('0b3af16e-4a55-524f-aa3b-6c69d4a417c7', v_en, $J$performance_indicator$J$, $J$The Universe · GB-2.3$J$, $J$Compares the water cycle, weather, or seasons as directly observable, present-day evidence for the same physical laws the Great Story described.$J$, $J$GB-2$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb2#pi3","ordinal":3,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('a607e3c1-8b2f-58c2-9e2a-6641ef10f571', v_en, $J$substrand$J$, $J$The Laws That Hold, Everywhere$J$, $J$Key concepts: Interconnectedness, Timeline Reasoning$J$, $J$GB-3$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb3","typicalGradeBand":"GB-3 (~10–12)","gradeBandId":"GB-3","gradeBandLabel":"Lower Secondary I","approxAge":"10–12","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-interconnectedness","emphasis":"primary"},{"id":"OE-CONCEPT-cosmic-k12-timeline-reasoning","emphasis":"reinforcing"}],"montessoriScope":"inside","crosswalks":[{"system":"sachsen-lehrplan","systemName":"Saxony Primary Curriculum (Lehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"LB 5: Begegnung mit Raum und Zeit (24 Ustd., Kl. 4); Wahlbereich 'Der Himmelsraum'","note":"Klassenstufe 4's named elective 'Der Himmelsraum' (outer space) is a direct, explicit match for Strand 1's content at the top of this LPM's own claimed range.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-interconnectedness","OE-CONCEPT-cosmic-k12-timeline-reasoning"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('cbdbef2a-f8be-5c35-bcad-f54b2ae9e5c6', v_en, $J$performance_indicator$J$, $J$The Universe · GB-3.1$J$, $J$Explains, using a specific example, how the same physical law (e.g. gravity's role in both planetary orbits and an object falling) operates at very different scales — connecting the Great Story's cosmic scale back to direct classroom-scale evidence.$J$, $J$GB-3$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb3#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('2a8ebf0d-2b5c-5d59-bffd-bb4b99bbdf1c', v_en, $J$performance_indicator$J$, $J$The Universe · GB-3.2$J$, $J$Places the formation of the universe, the solar system, and Earth on a shared timeline using consistent, comparable units of deep time, distinguishing it from the much shorter timeline of human history covered in Strand 3.$J$, $J$GB-3$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb3#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('305d9531-fcb7-5d1f-98aa-869e2e76848a', v_en, $J$performance_indicator$J$, $J$The Universe · GB-3.3$J$, $J$Identifies one open scientific question about the universe's origin or structure that scientists have not yet settled, distinguishing settled physical law from active research frontier.$J$, $J$GB-3$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb3#pi3","ordinal":3,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('147c4505-ebec-5383-9a59-2690b8559b22', v_en, $J$substrand$J$, $J$Bridge: Physical Science Beyond Cosmic Education's Own Scope$J$, NULL, $J$GB-4$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb4","typicalGradeBand":"GB-4 (~12–14)","gradeBandId":"GB-4","gradeBandLabel":"Lower Secondary II","approxAge":"12–14","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[{"system":"big-history-project","systemName":"OER Project — Big History Project (Eight Thresholds)","systemType":"state-standards","code":"Thresholds 1-4: The Big Bang; Stars Light Up; New Chemical Elements; Earth and the Solar System","note":"The single clearest continuation path for Strand 1 past this LPM's own GB-3 ceiling: a free, real, secondary-level curriculum covering the identical subject matter with age-appropriate depth, rather than a school needing to invent its own bridge.","noteLanguage":"en","confidence":"confirmed","concepts":[],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('a5c1b101-8a59-5fb0-a90d-93df1bd6d0c4', v_en, $J$performance_indicator$J$, $J$The Universe · GB-4.1$J$, $J$This band is deliberately left without Montessori-sourced content — Cosmic Education's own claimed scope ends at approximately age 12 (see grade-bands.yaml). A school continuing past that point should hand off to a conventional physical-science sequence, or to oe-interdisciplinary-k12's own 6-8/9-12 strands, rather than expect this LPM to supply invented content here.$J$, $J$GB-4$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb4#pi1","ordinal":1,"kind":"handoff-note","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('911af1d3-d601-5c10-92b4-21c41c9286f9', v_en, $J$substrand$J$, $J$Bridge: Beyond Cosmic Education's Own Scope$J$, NULL, $J$GB-5$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb5","typicalGradeBand":"GB-5 (~14–16)","gradeBandId":"GB-5","gradeBandLabel":"Upper Secondary I","approxAge":"14–16","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('1f567ff5-8320-55ea-ae4b-aa874f066cff', v_en, $J$substrand$J$, $J$Bridge: Beyond Cosmic Education's Own Scope$J$, NULL, $J$GB-6$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb6","typicalGradeBand":"GB-6 (~16–19)","gradeBandId":"GB-6","gradeBandLabel":"Upper Secondary II","approxAge":"16–19","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('9b3caad2-8c3a-5b9b-86f9-8fc2058178f5', v_en, $J$strand$J$, $J$The Story of Life$J$, $J$Montessori's Second Great Lesson: the appearance and change of life on Earth across deep time, told through the Timeline of Life and the Clock of Eras — plants and animals appearing, changing, and often disappearing across the Paleozoic, Mesozoic, and Cenozoic. Where Cosmic Education's own affective "Cosmic Task" framing (every living thing plays a role serving the whole) meets evolutionary biology's own hard-won distinction between legitimate and illegitimate purposive language most directly — this strand names that tension explicitly at GB-3 rather than leaving it implicit, the strand-specific reason this LPM's README treats it as a genuine open research question.$J$, NULL, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life","sequence":2,"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands; Montessori's own claimed scope is GB-1–GB-3, ~ages 6–12; GB-4+ hands off to oe-interdisciplinary-k12)","associatedDomains":["Biology","Science"],"relations":{"foundationalTo":["OE-STRAND-cosmic-education-k12-story-of-humans"],"parallel":[]},"homeAnchors":[{"id":"cross-species-comparisons","label":"Cross-Species Comparisons","description":"Comparing humans to other living things to ask what's shared and what's distinct."},{"id":"ancient-ancestors","label":"Ancient Ancestors","description":"Deep human and pre-human history as a source of perspective on the present."}],"thinkingTool":{"id":"tinbergens-four-questions","label":"Tinbergen's Four Questions","description":"Separates four distinct kinds of explanation for a trait or behavior: immediate mechanism, developmental history, present-day function, evolutionary origin — applied to Strand 2's life-history content at the top of this LPM's range."},"essentialQuestion":{"broad":"How has life on Earth changed, and what does 'change' mean across such enormous stretches of time?","worked":"Montessori's Cosmic Task says every living thing has a role that serves the whole. A biologist says a trait persists because it helped past generations survive and reproduce, not because anything needed it. Are these the same idea told two ways, or genuinely different claims — and does it matter which one a child comes away believing?"},"ecosystemConnections":[{"id":"life-to-interdisciplinary-k12","repo":"oe-interdisciplinary-k12","kind":"continues-into","title":"Continues into: oe-interdisciplinary-k12's Strand 1 (Inheritance/Variation/Selection)","description":"This LPM deliberately does not re-teach formal natural selection or genetics — that real, grade-band-mapped content already exists as oe-interdisciplinary-k12's own 6-8 and 9-12 bands (and bio-core-k12's parallel single-vocabulary treatment), ready for a school to hand off to directly."},{"id":"life-teleology-tension","repo":"theorybase","kind":"names-tension-with","title":"Names a real tension with: theorybase's selection-teleology proposition","description":"Strand 2's GB-3 band is the one place in this LPM where Montessori's own 'Cosmic Task' framing is put directly alongside this ecosystem's real, recorded position on legitimate vs. illegitimate purposive language in evolutionary explanation (OE-PROPOSITION-selection-teleology-legitimate) — an open empirical question about how the framing actually lands in children's reasoning, not resolved here."}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('fc939cc8-d5ae-5c43-bd32-860034cb4be1', v_en, $J$substrand$J$, $J$Noticing Living and Non-Living Things$J$, NULL, $J$GB-0$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb0","typicalGradeBand":"GB-0 (~3–6)","gradeBandId":"GB-0","gradeBandLabel":"Early Childhood","approxAge":"3–6","required":false,"concepts":[],"montessoriScope":"informal-precursor","crosswalks":[{"system":"sachsen-lehrplan","systemName":"Saxony Primary Curriculum (Lehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"vor der Schulpflicht","note":"Kita falls before compulsory schooling and outside the Sachsen Lehrplan's scope entirely — this LPM's own GB-0 band is likewise an informal, non-Montessori-sourced precursor, so the two align in having no formal content here, not by coincidence.","noteLanguage":"en","confidence":"confirmed","concepts":[],"appliesToAllStrands":true}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('8752044f-a48a-5105-834e-52e5fb174a2e', v_en, $J$performance_indicator$J$, $J$Life · GB-0.1$J$, $J$Sorts familiar objects into living and non-living through direct sensory experience, with no formal content expectation — an informal precursor this repo adds, not part of Montessori's own Second Great Lesson.$J$, $J$GB-0$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb0#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('7e45870a-49b6-50d7-a281-c096d4969702', v_en, $J$substrand$J$, $J$The Timeline of Life, First Telling$J$, $J$Key concepts: Great Story, Timeline Reasoning, Cosmic Task$J$, $J$GB-1$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb1","typicalGradeBand":"GB-1 (~6–8)","gradeBandId":"GB-1","gradeBandLabel":"Primary I","approxAge":"6–8","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-great-story","emphasis":"reinforcing"},{"id":"OE-CONCEPT-cosmic-k12-timeline-reasoning","emphasis":"primary"},{"id":"OE-CONCEPT-cosmic-k12-cosmic-task","emphasis":"primary"}],"montessoriScope":"inside","crosswalks":[{"system":"montessori-tradition","systemName":"Montessori Cosmic Education (native tradition)","systemType":"pedagogical-tradition","code":"Second Great Lesson: 'The Coming of Life' — first telling","note":"Confirmed named lesson and its first telling, typically following the First Great Lesson within the same term.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-timeline-reasoning"],"appliesToAllStrands":false},{"system":"sachsen-lehrplan","systemName":"Saxony Primary Curriculum (Lehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"LB 3: Begegnungen mit Pflanzen und Tieren (45 Ustd., Kl. 1/2)","note":"The largest single Lernbereich at this Klassenstufe (45 of roughly 130 total hours) — a real, substantial home for Strand 2's early plant/animal-life content, though the source does not itself reference Montessori or a timeline-of-life framing.","noteLanguage":"en","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-timeline-reasoning","OE-CONCEPT-cosmic-k12-cosmic-task"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('4e887964-1f6b-5b92-8a97-6b83a053b50e', v_en, $J$performance_indicator$J$, $J$Life · GB-1.1$J$, $J$Listens to and retells, using the Timeline of Life or an equivalent visual, the broad sequence in which major forms of life appeared, without requiring formal era names yet.$J$, $J$GB-1$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb1#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('ba3dc817-5130-5996-bd28-da93908c1d73', v_en, $J$performance_indicator$J$, $J$Life · GB-1.2$J$, $J$Names one simple way a living thing helps another living thing or its environment (e.g. a plant makes oxygen; a worm loosens soil) as an early, felt-level, child-scale introduction to the Cosmic Task idea — deliberately not yet framed as a formal biological claim.$J$, $J$GB-1$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb1#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('80907b21-260d-505f-8e41-82aa856aa017', v_en, $J$performance_indicator$J$, $J$Life · GB-1.3$J$, $J$Not covered at this band: formal genetics, natural selection mechanics, or the terms 'variation'/'selection'/'inheritance' — that vocabulary belongs to oe-interdisciplinary-k12's own K-2 band; this substrand stays at the impressionistic-story level Montessori's own elementary sequence uses first.$J$, $J$GB-1$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb1#pi3","ordinal":3,"kind":"scope-note","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('526da625-d751-50b0-8195-db7d4c3bf8bf', v_en, $J$substrand$J$, $J$The Clock of Eras and Going Out Into Biology$J$, $J$Key concepts: Timeline Reasoning, Going Out$J$, $J$GB-2$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb2","typicalGradeBand":"GB-2 (~8–10)","gradeBandId":"GB-2","gradeBandLabel":"Primary II","approxAge":"8–10","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-timeline-reasoning","emphasis":"reinforcing"},{"id":"OE-CONCEPT-cosmic-k12-going-out","emphasis":"primary"}],"montessoriScope":"inside","crosswalks":[{"system":"ib-pyp","systemName":"IB Primary Years Programme — Six Transdisciplinary Themes","systemType":"state-standards","code":"How the World Works","note":"Confirmed theme name; Strand 2's life-history content sits under the same PYP theme as Strand 1, reflecting that the PYP's six themes are broader groupings than this LPM's own five strands, not a 1:1 mapping.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-timeline-reasoning"],"appliesToAllStrands":false},{"system":"montessori-tradition","systemName":"Montessori Cosmic Education (native tradition)","systemType":"pedagogical-tradition","code":"Timeline of Life; Clock of Eras; the Long Black Line","note":"Confirmed named materials: the Timeline of Life charts the Paleozoic, Mesozoic, and Cenozoic eras; the Clock of Eras is a proportional deep-time visualization; the Long Black Line represents Earth's full history at a scale that makes human existence visually negligible by comparison — historically used, per multiple sources, as a deliberate lesson in humility and scale.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-timeline-reasoning"],"appliesToAllStrands":false},{"system":"sachsen-anhalt-lehrplan","systemName":"Saxony-Anhalt Primary Curriculum (Fachlehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"Naturwissenschaftlicher Bereich, Schuljahrgang 2 und 4: 'Pflanzen und Tiere'","note":"Confirmed: end-of-Schuljahrgang-4 competencies explicitly require grasping 'grundlegende Zusammenhänge zwischen der lebenden und nicht lebenden Natur' (basic connections between living and non-living nature) — the Lehrplan's own words for exactly Strand 2's Interconnectedness content.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-going-out"],"appliesToAllStrands":false},{"system":"thueringen-lehrplan","systemName":"Thuringia Primary Curriculum (Lehrplan Heimat- und Sachkunde)","systemType":"state-standards","code":"Lernbereich: Lebewesen und Lebensräume","note":"'Living Things and Habitats' is a direct name-level match for Strand 2's content, and the Thüringer Schulportal's own sample instructional topics for this Lernbereich include weather, stars and planets, and sensory organs — real, confirmed topic names, though not tied to a specific Klassenstufe in what could be extracted this session.","noteLanguage":"en","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-interconnectedness"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('6dbbd64f-5a5b-59d1-9840-274ddc8fc4df', v_en, $J$performance_indicator$J$, $J$Life · GB-2.1$J$, $J$Uses the Clock of Eras (or an equivalent proportional representation of deep time) to compare how much of Earth's history different forms of life have existed for — e.g. how small a proportion of the clock represents all of human existence.$J$, $J$GB-2$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb2#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('f3b0a42c-3fe4-5d1a-bdc5-f11d7e293c9e', v_en, $J$performance_indicator$J$, $J$Life · GB-2.2$J$, $J$Plans and carries out a self-directed 'Going Out' research follow-up on a specific extinct or living group of organisms the Timeline of Life raised curiosity about.$J$, $J$GB-2$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb2#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('8ffb59b6-31f1-5947-96b6-ad4e2240fadb', v_en, $J$performance_indicator$J$, $J$Life · GB-2.3$J$, $J$Classifies living things using a simple system (e.g. kingdom-level groupings) as concrete evidence that life's diversity has an organized structure, connecting the story back to observable present-day biology.$J$, $J$GB-2$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb2#pi3","ordinal":3,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('31ab34da-ccd7-5220-b7ab-43843df78d6c', v_en, $J$substrand$J$, $J$One Role or One Consequence? Naming the Tension$J$, $J$Key concepts: Cosmic Task, Evolutionary Process$J$, $J$GB-3$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb3","typicalGradeBand":"GB-3 (~10–12)","gradeBandId":"GB-3","gradeBandLabel":"Lower Secondary I","approxAge":"10–12","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-cosmic-task","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-evolutionary-process","emphasis":"reinforcing"}],"montessoriScope":"inside","crosswalks":[{"system":"montessori-tradition","systemName":"Montessori Cosmic Education (native tradition)","systemType":"pedagogical-tradition","code":"Upper Elementary deepening: Cosmic Task discussions, biome/ecosystem research","note":"Upper Elementary's own documented deepening of Cosmic Task content into more explicit ecological-role discussion — the exact material this LPM's GB-3 substrand names the teleology tension in.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-cosmic-task"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('34f00ab2-6901-526e-ba0a-9f525e8ec95d', v_en, $J$performance_indicator$J$, $J$Life · GB-3.1$J$, $J$Explains, in their own words, both the Cosmic Task account of why a trait exists (it serves a role the whole system needs) and a selection-based account (it persisted because it helped past individuals survive and reproduce more than alternatives did) for the same real example (e.g. a bird's beak shape, a plant's thorns).$J$, $J$GB-3$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb3#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('b0468193-24d8-5bc8-801c-c63c9c5d0986', v_en, $J$performance_indicator$J$, $J$Life · GB-3.2$J$, $J$Identifies, when given two sentences about the same trait, which one is describing what the trait does now (its current role) and which is describing why it came to exist historically (its selective history) — the K-12-appropriate entry point to this LPM's own core research question about how Cosmic Task language actually lands in children's reasoning.$J$, $J$GB-3$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb3#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('7a91a087-1a97-5c11-8f3c-0d470b351c85', v_en, $J$performance_indicator$J$, $J$Life · GB-3.3$J$, $J$Applies Tinbergen's Four Questions (mechanism, development, function, evolutionary origin) to one example from the Timeline of Life, explicitly separating 'what does it do' from 'why did it evolve' as two different, both-legitimate questions rather than one question with one answer.$J$, $J$GB-3$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb3#pi3","ordinal":3,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('b7ae7952-7238-530f-98fe-8396426981a5', v_en, $J$substrand$J$, $J$Hand-off: Formal Evolutionary Biology$J$, NULL, $J$GB-4$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb4","typicalGradeBand":"GB-4 (~12–14)","gradeBandId":"GB-4","gradeBandLabel":"Lower Secondary II","approxAge":"12–14","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[{"system":"big-history-project","systemName":"OER Project — Big History Project (Eight Thresholds)","systemType":"state-standards","code":"Threshold 5: Life on Earth","note":"Confirmed threshold name and position — the natural continuation for Strand 2 past age 12, alongside oe-interdisciplinary-k12's own formal evolutionary-biology strands (see strand-2-life.yaml's own GB-4 note for the ecosystem-internal alternative).","noteLanguage":"en","confidence":"confirmed","concepts":[],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('488b169b-ba54-5b72-b8ec-bc90c6c592a8', v_en, $J$performance_indicator$J$, $J$Life · GB-4.1$J$, $J$This LPM deliberately does not re-teach formal natural selection, genetics, or inheritance mechanics here — that content already exists, real and grade-band-mapped, as oe-interdisciplinary-k12's own Strand 1 (inheritance/variation/selection) 6-8 and 9-12 bands, and as bio-core-k12's parallel single-vocabulary treatment. A school continuing a Cosmic-Education-rooted sequence past age 12 should hand off to one of those two LPMs directly rather than expect duplicated content here.$J$, $J$GB-4$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb4#pi1","ordinal":1,"kind":"handoff-note","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('4e1508ca-e567-5210-9ebc-69c0abb2f7ae', v_en, $J$substrand$J$, $J$Bridge: Beyond Cosmic Education's Own Scope$J$, NULL, $J$GB-5$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb5","typicalGradeBand":"GB-5 (~14–16)","gradeBandId":"GB-5","gradeBandLabel":"Upper Secondary I","approxAge":"14–16","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('0b1c7ecb-5bfd-5882-b97b-8d85bf36e307', v_en, $J$substrand$J$, $J$Bridge: Beyond Cosmic Education's Own Scope$J$, NULL, $J$GB-6$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb6","typicalGradeBand":"GB-6 (~16–19)","gradeBandId":"GB-6","gradeBandLabel":"Upper Secondary II","approxAge":"16–19","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('b9375d69-9ee2-57fd-8566-cdc5a9237699', v_en, $J$strand$J$, $J$The Story of Humans$J$, $J$Montessori's Third Great Lesson: the coming of humans, the timeline of hominids, and — its own named organizing device — Fundamental Human Needs (physical: food, shelter, defense, transportation; spiritual/psychological: art, religion, music, a sense of significance) met in different ways by every human culture across every period of history. The strand where Cosmic Education's own cross-cultural, multiply-realized-solutions framing runs structurally parallel to evolutionary anthropology's own treatment of universal human needs and variable cultural solutions — the specific parallel this LPM's own synthesis draws to eva_buch (Hanisch, forthcoming), not a claim either source makes about the other.$J$, NULL, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans","sequence":3,"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands; Montessori's own claimed scope is GB-1–GB-3, ~ages 6–12)","associatedDomains":["History","Social Studies","Ethics/Religion","Geography"],"relations":{"foundationalTo":["OE-STRAND-cosmic-education-k12-story-of-language","OE-STRAND-cosmic-education-k12-story-of-numbers"],"parallel":[]},"homeAnchors":[{"id":"ancient-ancestors","label":"Ancient Ancestors","description":"Deep human and pre-human history as a source of perspective on the present."},{"id":"cultural-diversity","label":"Cultural Diversity","description":"How different human groups solve the same fundamental needs differently."},{"id":"cooperation-games","label":"Cooperation Games","description":"Simple structures for reasoning about when cooperation pays off for a group."}],"thinkingTool":{"id":"payoff-matrices","label":"Payoff Matrices","description":"Tables laying out costs and benefits of different choices for different actors — used where Strand 3's fundamental-needs content turns to cooperation and division of labor."},"essentialQuestion":{"broad":"What do all humans need, and how differently have people met those same needs?","worked":"Every known human group has had to solve the same handful of problems — food, shelter, safety, meaning. A class comparing how three very different cultures solved 'shelter' is doing something evolutionary anthropology also does with 'cooperation' or 'fairness' — what changes, and what stays the same, when the same comparative method is applied to a physical need versus a social one?"},"ecosystemConnections":[{"id":"humans-to-eva-buch","repo":"eva_buch","kind":"structural-parallel","title":"Structural parallel: eva_buch's evolutionary-anthropology-as-interdisciplinary-spine","description":"Susan Hanisch's forthcoming Springer book treats evolutionary anthropology as the interdisciplinary spine for Sozialkunde, Ethik/Philosophie, Geschichte, and Psychologie curricula across all German Bundesländer. Strand 3's own 'one need, many culturally variable solutions' framing runs structurally parallel to that argument — independently arrived at, not cited by either source."},{"id":"humans-to-osci-timeline","repo":"oSci","kind":"draws-on","title":"Draws on: oSci's page-verified prehistoric-technology timeline","description":"oSci's data/timeline/ records (control of fire, Acheulean hand-axes, first Levallois stone tools, art/beads) are real, page-verified extraction from Feist (2006) — a genuine evidence base Strand 3's GB-2 performance indicators reference rather than re-deriving the history independently."}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('99c15457-ee1a-526e-a738-9d2ef6d222cd', v_en, $J$substrand$J$, $J$Noticing What People Need$J$, NULL, $J$GB-0$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb0","typicalGradeBand":"GB-0 (~3–6)","gradeBandId":"GB-0","gradeBandLabel":"Early Childhood","approxAge":"3–6","required":false,"concepts":[],"montessoriScope":"informal-precursor","crosswalks":[{"system":"sachsen-lehrplan","systemName":"Saxony Primary Curriculum (Lehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"vor der Schulpflicht","note":"Kita falls before compulsory schooling and outside the Sachsen Lehrplan's scope entirely — this LPM's own GB-0 band is likewise an informal, non-Montessori-sourced precursor, so the two align in having no formal content here, not by coincidence.","noteLanguage":"en","confidence":"confirmed","concepts":[],"appliesToAllStrands":true}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('47da1b1a-a8fb-50a2-8a89-2914a56e258e', v_en, $J$performance_indicator$J$, $J$Humans · GB-0.1$J$, $J$Names basic needs (food, a safe place to sleep) from direct personal experience, with no formal content expectation — an informal precursor this repo adds, not part of Montessori's own Third Great Lesson.$J$, $J$GB-0$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb0#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('0d0fcab8-a1e2-56f1-9099-f46f7b983601', v_en, $J$substrand$J$, $J$The Coming of Humans, First Telling$J$, $J$Key concepts: Great Story, Fundamental Human Needs$J$, $J$GB-1$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb1","typicalGradeBand":"GB-1 (~6–8)","gradeBandId":"GB-1","gradeBandLabel":"Primary I","approxAge":"6–8","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-great-story","emphasis":"reinforcing"},{"id":"OE-CONCEPT-cosmic-k12-fundamental-human-needs","emphasis":"primary"}],"montessoriScope":"inside","crosswalks":[{"system":"montessori-tradition","systemName":"Montessori Cosmic Education (native tradition)","systemType":"pedagogical-tradition","code":"Third Great Lesson: 'The Coming of Humans' — Fundamental Needs Chart","note":"Confirmed named lesson and its own named follow-up material: the Human History Timeline and Fundamental Needs of Humans chart, per the Global Montessori Network and multiple independent Montessori-practitioner sources describing it as the direct Primary-and-Elementary follow-up material.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-fundamental-human-needs"],"appliesToAllStrands":false},{"system":"sachsen-anhalt-lehrplan","systemName":"Saxony-Anhalt Primary Curriculum (Fachlehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"Erkunden (Prozesskompetenz, Endniveau Schuljahrgang 4)","note":"The Lehrplan's own process-competency 'Erkunden' (exploring) is defined as investigating the unclear and puzzling from a child's lived world using tools and media — the same self-directed-inquiry disposition Strand 3's Fundamental Needs content and this LPM's own 'Going Out' concept both name.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-fundamental-human-needs"],"appliesToAllStrands":false},{"system":"sachsen-lehrplan","systemName":"Saxony Primary Curriculum (Lehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"LB 2: Mein Körper und meine Gesundheit (20 Ustd., Kl. 1/2)","note":"Body and health content is the Sachsen curriculum's own entry point for a child's basic physical needs, the natural anchor for Strand 3's earliest Fundamental Needs content.","noteLanguage":"en","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-fundamental-human-needs"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('56258bb5-b1ba-5a35-a8e2-b1583eabcf3f', v_en, $J$performance_indicator$J$, $J$Humans · GB-1.1$J$, $J$Listens to and retells the broad story of humans appearing on the Timeline of Life, placed after the much longer stretch of time covered by Strand 2.$J$, $J$GB-1$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb1#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('e5c69898-2e5d-5667-8b2a-61a37c63cb61', v_en, $J$performance_indicator$J$, $J$Humans · GB-1.2$J$, $J$Names at least two physical needs (food, shelter) and at least one spiritual/psychological need (e.g. wanting to make something beautiful, wanting to belong to a group) every person has, as an early, felt-level entry into the Fundamental Needs framework.$J$, $J$GB-1$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb1#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('93fec4d5-636f-5853-8885-94c7bb43f5fb', v_en, $J$substrand$J$, $J$One Need, Many Solutions$J$, $J$Key concepts: Cultural Diversity of Solutions, Going Out$J$, $J$GB-2$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb2","typicalGradeBand":"GB-2 (~8–10)","gradeBandId":"GB-2","gradeBandLabel":"Primary II","approxAge":"8–10","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-cultural-diversity-of-solutions","emphasis":"primary"},{"id":"OE-CONCEPT-cosmic-k12-going-out","emphasis":"reinforcing"}],"montessoriScope":"inside","crosswalks":[{"system":"gdsu-perspektivrahmen","systemName":"GDSU Perspektivrahmen Sachunterricht (national didactic framework)","systemType":"national-framework","code":"Sozial- und kulturwissenschaftliche Perspektive; PVT: Identität","note":"Inferred perspective name for the base discipline, but the PVT 'Identität' is confirmed real and current, and is a strong match for Strand 3's cross-cultural comparison content.","noteLanguage":"en","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-cultural-diversity-of-solutions"],"appliesToAllStrands":false},{"system":"ib-pyp","systemName":"IB Primary Years Programme — Six Transdisciplinary Themes","systemType":"state-standards","code":"Where We Are in Place and Time; Sharing the Planet","note":"Confirmed theme names; Strand 3's fundamental-needs-met-differently-across-cultures content spans both themes — 'Where We Are in Place and Time' for the historical/cultural comparison, 'Sharing the Planet' for the shared-resource/cooperation angle.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-fundamental-human-needs","OE-CONCEPT-cosmic-k12-cultural-diversity-of-solutions"],"appliesToAllStrands":false},{"system":"sachsen-lehrplan","systemName":"Saxony Primary Curriculum (Lehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"LB 1: Zusammen leben und lernen (7 Ustd., Kl. 3); Wahlbereich 'Steine und steinerne Kultur in der Region'","note":"Klassenstufe 3's named elective 'Stones and stone culture in the region' is a real, directly citable example of exactly the kind of local-culture, cultural-diversity-of-solutions content Strand 3's GB-2 band asks for.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-cultural-diversity-of-solutions"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('9af956d3-59da-5af8-baff-5caf135c3563', v_en, $J$performance_indicator$J$, $J$Humans · GB-2.1$J$, $J$Compares at least three different cultures' or time periods' solutions to the same physical need (e.g. shelter: igloo, yurt, longhouse), naming what's shared about the underlying need and what's genuinely different about the solution — the concrete, K-12-appropriate version of this ecosystem's own 'one need, many culturally variable solutions' reading of evolutionary anthropology.$J$, $J$GB-2$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb2#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('6102e384-d60b-5db2-8c0e-137dc6896124', v_en, $J$performance_indicator$J$, $J$Humans · GB-2.2$J$, $J$Describes one piece of concrete evidence for early human technology (e.g. control of fire, early stone tools) as a real historical achievement, not a myth or a guess — drawing on real, page-verified prehistoric-technology timeline material where available (oSci's own extraction).$J$, $J$GB-2$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb2#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('74d6529c-c820-5b8f-85fd-6130869b7c33', v_en, $J$performance_indicator$J$, $J$Humans · GB-2.3$J$, $J$Plans and carries out a self-directed 'Going Out' research follow-up comparing how one specific need was met in two cultures of the child's own choosing.$J$, $J$GB-2$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb2#pi3","ordinal":3,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('0e4e1877-f918-5732-8caa-6a5b1fbb1cf2', v_en, $J$substrand$J$, $J$Needs, Cooperation, and Fairness$J$, $J$Key concepts: Fundamental Human Needs, Culture$J$, $J$GB-3$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb3","typicalGradeBand":"GB-3 (~10–12)","gradeBandId":"GB-3","gradeBandLabel":"Lower Secondary I","approxAge":"10–12","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-fundamental-human-needs","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-culture","emphasis":"reinforcing"}],"montessoriScope":"inside","crosswalks":[{"system":"gdsu-perspektivrahmen","systemName":"GDSU Perspektivrahmen Sachunterricht (national didactic framework)","systemType":"national-framework","code":"Historische Perspektive; PVT: Frieden, Demokratie","note":"Inferred perspective name; the confirmed, current PVTs 'Frieden' (peace) and 'Demokratie' are a strong, directly relevant match for Strand 3's GB-3 anti-ethnocentrism and cooperation content, and are explicitly named in the GDSU Journal's own 2026 lead article as 'aktuell besonders notwendig' (currently especially necessary).","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-fundamental-human-needs"],"appliesToAllStrands":false},{"system":"sachsen-anhalt-lehrplan","systemName":"Saxony-Anhalt Primary Curriculum (Fachlehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"Historischer Bereich, Schuljahrgang 4: 'Veränderung und Entwicklung des Handelns der Menschen in vergangenen und gegenwärtigen Situationen'","note":"Confirmed, and a strong match: the Historischer Bereich's end-of-Schuljahrgang-4 competency explicitly requires comparing present-day and past human behavior including 'Bodenbearbeitung, Bestellung, Pflege und Ernte in der Landwirtschaft früher und heute' and changes in household appliances, transport, and media — real curriculum content that is, structurally, exactly Strand 3's 'one need, many solutions across time' claim, independently arrived at by Sachsen-Anhalt's own Lehrplan authors.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-fundamental-human-needs","OE-CONCEPT-cosmic-k12-cultural-diversity-of-solutions"],"appliesToAllStrands":false},{"system":"sachsen-lehrplan","systemName":"Saxony Primary Curriculum (Lehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"LB 1: Zusammen leben und lernen (12 Ustd., Kl. 4); Wahlbereich 'Schlösser, Burgen und Gärten in Sachsen'","note":"Klassenstufe 4's largest Lernbereich-1 allocation of any grade (12 hours) plus a named regional-history elective give real room for Strand 3's culture/cooperation content at this band.","noteLanguage":"en","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-fundamental-human-needs","OE-CONCEPT-oe-interdisciplinary-culture"],"appliesToAllStrands":false},{"system":"thueringen-lehrplan","systemName":"Thuringia Primary Curriculum (Lehrplan Heimat- und Sachkunde)","systemType":"state-standards","code":"Lernbereich: Natur und Technik","note":"'Nature and Technology' is the most plausible Thüringen anchor for Strand 3's technology-and-needs content, by name alone — genuinely uncertain pending a working full-text extraction of the source Lehrplan.","noteLanguage":"en","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-fundamental-human-needs"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('ff2abc22-3102-540b-90ed-42e183d1a4c3', v_en, $J$performance_indicator$J$, $J$Humans · GB-3.1$J$, $J$Explains, using a payoff-matrix-style comparison, why groups meeting a shared need (e.g. defense, large-scale food production) often had to cooperate to succeed, and names at least one real historical or present-day example.$J$, $J$GB-3$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb3#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('c42d58d5-aecd-5e21-b709-9ad5cdd837b7', v_en, $J$performance_indicator$J$, $J$Humans · GB-3.2$J$, $J$Distinguishes a need (universal, shared by all humans) from a solution (culturally variable, historically specific) when given a real example, and explains why collapsing the two together can lead to treating one culture's solution as the only correct one — an explicit anti-ethnocentrism performance indicator, matching Sachunterricht's own named Rassismuskritik/Vorurteil concerns (GDSU Journal 2026, Warburg & Seifert).$J$, $J$GB-3$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb3#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('ea0680b6-8d26-5d45-9f2f-7beac03712b0', v_en, $J$performance_indicator$J$, $J$Humans · GB-3.3$J$, $J$Identifies one open historical or anthropological question about early human life that is still actively researched, distinguishing well-evidenced claims from open questions.$J$, $J$GB-3$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb3#pi3","ordinal":3,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('3a1e2abc-ce19-502f-b6a7-dad4791f4771', v_en, $J$substrand$J$, $J$Bridge: Evolutionary Anthropology Across the Curriculum$J$, NULL, $J$GB-4$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb4","typicalGradeBand":"GB-4 (~12–14)","gradeBandId":"GB-4","gradeBandLabel":"Lower Secondary II","approxAge":"12–14","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[{"system":"big-history-project","systemName":"OER Project — Big History Project (Eight Thresholds)","systemType":"state-standards","code":"Thresholds 6-7: Collective Learning; Agriculture","note":"Confirmed threshold names — 'Collective Learning' in particular is Big History Project's own name for essentially the same phenomenon Strand 3's Fundamental Needs content and eva_buch's evolutionary-anthropology framing both treat as central: cumulative, cross-generational cultural knowledge accumulation, named independently by a third source.","noteLanguage":"en","confidence":"confirmed","concepts":[],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('8504080e-58ea-561d-a51f-c59f996157f0', v_en, $J$performance_indicator$J$, $J$Humans · GB-4.1$J$, $J$This LPM deliberately does not extend Fundamental Needs content into formal secondary evolutionary-anthropology coursework here — that is exactly eva_buch's (Hanisch, forthcoming Springer 2027) own subject, built for Biologie, Ethik/Philosophie, Sozialkunde, Geschichte, and Psychologie at the secondary level. A school continuing a Cosmic-Education-rooted sequence past age 12 should look to that book and its companion Lehrplananalyse app, not expect duplicated content here.$J$, $J$GB-4$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb4#pi1","ordinal":1,"kind":"handoff-note","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('05789d33-f66d-585b-bd7b-447f66709568', v_en, $J$substrand$J$, $J$Bridge: Beyond Cosmic Education's Own Scope$J$, NULL, $J$GB-5$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb5","typicalGradeBand":"GB-5 (~14–16)","gradeBandId":"GB-5","gradeBandLabel":"Upper Secondary I","approxAge":"14–16","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('466d0f23-914f-5ca1-9fc4-9ff6055df744', v_en, $J$substrand$J$, $J$Bridge: Beyond Cosmic Education's Own Scope$J$, NULL, $J$GB-6$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb6","typicalGradeBand":"GB-6 (~16–19)","gradeBandId":"GB-6","gradeBandLabel":"Upper Secondary II","approxAge":"16–19","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('91a95e9f-3180-50a1-919d-0938fbd693cf', v_en, $J$strand$J$, $J$The Story of Language$J$, $J$Montessori's Fourth Great Lesson: how humans came to represent sounds and ideas with arbitrary marks — signs, pictographs, alphabets — and how that single invention let knowledge accumulate and transmit across generations beyond what direct memory could carry. Read alongside oe-interdisciplinary-k12's Strand 204, which treats analogical reasoning and the "growth of understanding" as a shared pattern across individual minds, cultures, and the history of science itself — this strand supplies that pattern's own historical origin story for the specific case of written language.$J$, NULL, $J$Language Arts$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-language","sequence":4,"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands; Montessori's own claimed scope is GB-1–GB-3, ~ages 6–12)","associatedDomains":["Language Arts","History","Social Studies"],"relations":{"parallel":["OE-STRAND-cosmic-education-k12-story-of-numbers"]},"homeAnchors":[{"id":"ancient-ancestors","label":"Ancient Ancestors","description":"Deep human and pre-human history as a source of perspective on the present."},{"id":"cultural-diversity","label":"Cultural Diversity","description":"How different human groups solve the same fundamental needs differently."}],"thinkingTool":{"id":"analogy-mapping","label":"Analogies & Analogy Mapping","description":"Structured, feature-by-feature comparison that names both what maps and what doesn't — used here across strands wherever one Great Lesson's pattern (variation-selection-transmission, needs-met-by-culture) recurs in another."},"essentialQuestion":{"broad":"How did marks on a surface come to carry meaning, and what changed once they could?","worked":"Every writing system humans have ever invented uses arbitrary marks agreed on by a group — nothing about the shape of a letter 'A' makes it mean what it means. What does a class gain by comparing several real writing systems side by side, instead of treating the one they're learning as the natural or obvious one?"},"ecosystemConnections":[{"id":"language-to-strand-204","repo":"oe-interdisciplinary-k12","kind":"structural-parallel","title":"Structural parallel: oe-interdisciplinary-k12's Strand 204 (Analogy, Search, and the Growth of Understanding)","description":"Strand 204 treats a shared pool of remembered solutions — a class's worked examples, a culture's toolkit — as what makes each new problem faster to solve, at every scale from individual minds to whole scientific fields. Strand 4's own claim (writing let knowledge accumulate beyond what memory alone could carry) is exactly this pattern applied to the specific historical case of written language."}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-4-language.yaml"}}$J$::jsonb, 'draft'),
  ('37b53d81-62df-53bc-a10d-2d9fa4435c7c', v_en, $J$substrand$J$, $J$Marks That Mean Something$J$, NULL, $J$GB-0$J$, $J$Language Arts$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-language-gb0","typicalGradeBand":"GB-0 (~3–6)","gradeBandId":"GB-0","gradeBandLabel":"Early Childhood","approxAge":"3–6","required":false,"concepts":[],"montessoriScope":"informal-precursor","crosswalks":[{"system":"sachsen-lehrplan","systemName":"Saxony Primary Curriculum (Lehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"vor der Schulpflicht","note":"Kita falls before compulsory schooling and outside the Sachsen Lehrplan's scope entirely — this LPM's own GB-0 band is likewise an informal, non-Montessori-sourced precursor, so the two align in having no formal content here, not by coincidence.","noteLanguage":"en","confidence":"confirmed","concepts":[],"appliesToAllStrands":true}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-4-language.yaml"}}$J$::jsonb, 'draft'),
