  ('40777506-9852-53aa-bf6a-027879bc3658', v_en, $J$substrand$J$, $J$What Writing Made Possible$J$, $J$Key concepts: Sign and Symbol, Transmission$J$, $J$GB-3$J$, $J$Language Arts$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-language-gb3","typicalGradeBand":"GB-3 (~10–12)","gradeBandId":"GB-3","gradeBandLabel":"Lower Secondary I","approxAge":"10–12","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-sign-and-symbol","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-transmission","emphasis":"reinforcing"}],"montessoriScope":"inside","crosswalks":[{"system":"gdsu-perspektivrahmen","systemName":"GDSU Perspektivrahmen Sachunterricht (national didactic framework)","systemType":"national-framework","code":"PVT: Digitalisierung und Medien","note":"Confirmed as a real, current PVT — Strand 4's own arc (marks that carry meaning, and what changes once they can be recorded and shared) is the historical/conceptual predecessor this PVT's own present-day digital-media content builds on, a connection this crosswalk makes explicit rather than leaving implicit.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-sign-and-symbol"],"appliesToAllStrands":false},{"system":"ib-pyp","systemName":"IB Primary Years Programme — Six Transdisciplinary Themes","systemType":"state-standards","code":"How We Express Ourselves","note":"Confirmed theme name — a direct match by name for Strand 4's communication-and-symbol content.","noteLanguage":"en","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-sign-and-symbol"],"appliesToAllStrands":false},{"system":"sachsen-anhalt-lehrplan","systemName":"Saxony-Anhalt Primary Curriculum (Fachlehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"Medienkompetenz (fachübergreifend, Endniveau Schuljahrgang 4)","note":"The Lehrplan's own cross-cutting Medienkompetenz section (developed 'inhaltsübergreifend', across all five content areas) is the closest Sachsen-Anhalt anchor for Strand 4's sign/symbol content, though the source frames it as critical media use rather than the history of writing systems.","noteLanguage":"en","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-sign-and-symbol"],"appliesToAllStrands":false},{"system":"sachsen-lehrplan","systemName":"Saxony Primary Curriculum (Lehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"LB 6: Medien – Informationsbeschaffung und -aufbereitung (3 Ustd., Kl. 4)","note":"The smallest Lernbereich by hours, but the only one in the whole Sachsen Sachunterricht Lehrplan that directly names information/media handling — the most plausible Sachsen anchor for Strand 4's 'what writing made possible' content, though the source itself frames this as media literacy, not writing history.","noteLanguage":"en","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-sign-and-symbol"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-4-language.yaml"}}$J$::jsonb, 'draft'),
  ('02833491-42d1-52ad-87b3-1c8c3823e30f', v_en, $J$performance_indicator$J$, $J$Language · GB-3.1$J$, $J$Explains how writing let knowledge accumulate beyond what any one person could remember or any one generation could pass on by speech alone — connecting this strand's own content directly to oe-interdisciplinary-k12 Strand 204's broader claim that minds, cultures, and science itself all search for better ideas by building on a shared, remembered pool of past solutions.$J$, $J$GB-3$J$, $J$Language Arts$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-language-gb3#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-4-language.yaml"}}$J$::jsonb, 'draft'),
