  ('784bc61a-0abe-5bf9-ba32-9b2b55db2f4e', v_en, $J$performance_indicator$J$, $J$Language · GB-4.1$J$, $J$This LPM hands off formal historical linguistics and secondary Deutsch/language-history content to conventional curricula or to oe-interdisciplinary-k12's Strand 204 rather than inventing overlapping content here.$J$, $J$GB-4$J$, $J$Language Arts$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-language-gb4#pi1","ordinal":1,"kind":"handoff-note","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-4-language.yaml"}}$J$::jsonb, 'draft'),
  ('48eaef78-95a6-5ed4-954c-e01a6c5ca731', v_en, $J$substrand$J$, $J$Bridge: Beyond Cosmic Education's Own Scope$J$, NULL, $J$GB-5$J$, $J$Language Arts$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-language-gb5","typicalGradeBand":"GB-5 (~14–16)","gradeBandId":"GB-5","gradeBandLabel":"Upper Secondary I","approxAge":"14–16","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-4-language.yaml"}}$J$::jsonb, 'draft'),
  ('f1aa3319-b36e-5271-a0c0-f0c0cec1ab5e', v_en, $J$substrand$J$, $J$Bridge: Beyond Cosmic Education's Own Scope$J$, NULL, $J$GB-6$J$, $J$Language Arts$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-language-gb6","typicalGradeBand":"GB-6 (~16–19)","gradeBandId":"GB-6","gradeBandLabel":"Upper Secondary II","approxAge":"16–19","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-4-language.yaml"}}$J$::jsonb, 'draft'),
  ('7fd68de1-56e2-593b-8d6c-e23e6a5e9a19', v_en, $J$strand$J$, $J$The Story of Numbers$J$, $J$Montessori's Fifth Great Lesson: how humans came to represent quantity with symbols — tallies, place value, zero — as a historical human achievement, not a fact of nature waiting to be discovered ready-made. The strand that makes explicit a claim this LPM treats as a genuine finding, not an assumption carried in from outside: that mathematics, told this way, is itself one of the Great Stories, structurally parallel to oSci's own selection-retention account of how minds, cultures, and the history of science each search for better ideas by building on a remembered pool of past solutions rather than starting from nothing each time.$J$, NULL, $J$Mathematics$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-numbers","sequence":5,"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands; Montessori's own claimed scope is GB-1–GB-3, ~ages 6–12)","associatedDomains":["Mathematics","History","Computer Science"],"relations":{"parallel":["OE-STRAND-cosmic-education-k12-story-of-language"]},"homeAnchors":[{"id":"computer-models","label":"Computer Models","description":"Simplified rule-based simulations used to reproduce and reason about complex real systems."},{"id":"ancient-ancestors","label":"Ancient Ancestors","description":"Deep human and pre-human history as a source of perspective on the present."}],"thinkingTool":{"id":"analogy-mapping","label":"Analogies & Analogy Mapping","description":"Structured, feature-by-feature comparison that names both what maps and what doesn't — used here across strands wherever one Great Lesson's pattern (variation-selection-transmission, needs-met-by-culture) recurs in another."},"essentialQuestion":{"broad":"Who invented numbers, and could counting have worked differently?","worked":"A base-10 place-value system with a zero is not the only way humans have ever represented quantity — other systems used different bases, or no place value at all, or no zero. If numbers themselves have a history and could have gone differently, what does that change about how a class should think about 'discovering' versus 'inventing' in mathematics?"},"ecosystemConnections":[{"id":"numbers-to-osci-synth","repo":"oSci","kind":"structural-parallel","title":"Structural parallel: oSci's recursive-selection synthesis","description":"oSci's own osci:synth:recursive-selection-mind-curriculum-science traces one variation/selection/retention pattern across individual cognition, cultural knowledge systems, and the history of science. Strand 5's claim that mathematics itself is one of the Great Stories — a real finding of this LPM, not assumed going in — names number-symbol systems as a further instance of that same pattern, the first place either repo makes that specific extension."},{"id":"numbers-to-strand-204","repo":"oe-interdisciplinary-k12","kind":"structural-parallel","title":"Structural parallel: oe-interdisciplinary-k12's Strand 204","description":"Strand 5's GB-3 claim — a new mathematical idea builds on and modifies earlier ideas rather than appearing from nothing — is a direct application of Strand 204's own 'starts from the closest known case, then improves it' account of how minds and cultures search for better ideas."}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-5-numbers.yaml"}}$J$::jsonb, 'draft'),
  ('6343a1d4-cec1-544a-a1c4-5ecd9520dda8', v_en, $J$substrand$J$, $J$Noticing How Many$J$, NULL, $J$GB-0$J$, $J$Mathematics$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-numbers-gb0","typicalGradeBand":"GB-0 (~3–6)","gradeBandId":"GB-0","gradeBandLabel":"Early Childhood","approxAge":"3–6","required":false,"concepts":[],"montessoriScope":"informal-precursor","crosswalks":[{"system":"sachsen-lehrplan","systemName":"Saxony Primary Curriculum (Lehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"vor der Schulpflicht","note":"Kita falls before compulsory schooling and outside the Sachsen Lehrplan's scope entirely — this LPM's own GB-0 band is likewise an informal, non-Montessori-sourced precursor, so the two align in having no formal content here, not by coincidence.","noteLanguage":"en","confidence":"confirmed","concepts":[],"appliesToAllStrands":true}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-5-numbers.yaml"}}$J$::jsonb, 'draft'),
