  ('d7b49f95-e9d7-5676-9a9d-46db7db72a0a', v_en, $J$performance_indicator$J$, $J$Numbers · GB-2.1$J$, $J$Compares at least two real historical number systems (e.g. Egyptian, Babylonian base-60, Roman, Mayan base-20) for how each represents quantity, naming what each can and cannot easily express.$J$, $J$GB-2$J$, $J$Mathematics$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-numbers-gb2#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-5-numbers.yaml"}}$J$::jsonb, 'draft'),
  ('5f9dd286-901b-5dd3-99bc-3b2fa45aa7e5', v_en, $J$performance_indicator$J$, $J$Numbers · GB-2.2$J$, $J$Plans a self-directed 'Going Out' research follow-up on the history of one specific number system or the invention of zero.$J$, $J$GB-2$J$, $J$Mathematics$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-numbers-gb2#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-5-numbers.yaml"}}$J$::jsonb, 'draft'),
  ('db21b09c-494c-5ed8-bd90-006617c7da3e', v_en, $J$performance_indicator$J$, $J$Numbers · GB-2.3$J$, $J$Explains place value using a system without it (e.g. Roman numerals) as a contrast case, making explicit why place value was itself a specific, historically locatable invention.$J$, $J$GB-2$J$, $J$Mathematics$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-numbers-gb2#pi3","ordinal":3,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-5-numbers.yaml"}}$J$::jsonb, 'draft'),
  ('a1aed355-88e8-52a4-8205-45bdca03ca59', v_en, $J$substrand$J$, $J$Mathematics as a Great Story$J$, $J$Key concepts: Quantity and Symbol, Innovation$J$, $J$GB-3$J$, $J$Mathematics$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-numbers-gb3","typicalGradeBand":"GB-3 (~10–12)","gradeBandId":"GB-3","gradeBandLabel":"Lower Secondary I","approxAge":"10–12","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-quantity-and-symbol","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-innovation","emphasis":"reinforcing"}],"montessoriScope":"inside","crosswalks":[{"system":"ib-pyp","systemName":"IB Primary Years Programme — Six Transdisciplinary Themes","systemType":"state-standards","code":"How We Organize Ourselves","note":"Confirmed theme name; number systems as a form of social/organizational technology fits this theme's own stated scope (how societies structure and organize shared undertakings), an inference this crosswalk makes rather than a claim taken directly from an IB source.","noteLanguage":"en","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-quantity-and-symbol"],"appliesToAllStrands":false},{"system":"sachsen-anhalt-lehrplan","systemName":"Saxony-Anhalt Primary Curriculum (Fachlehrplan Grundschule Sachunterricht)","systemType":"state-standards","code":"Mathematische Kompetenz (fachübergreifend, Endniveau Schuljahrgang 4)","note":"Confirmed as a named cross-cutting competency, applying units, measurement, and data representation to real Sachunterricht problems — the Lehrplan's own bridge between Sachunterricht and Mathematik, though it does not itself raise the history of number systems Strand 5 centers.","noteLanguage":"en","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-quantity-and-symbol"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-5-numbers.yaml"}}$J$::jsonb, 'draft'),
  ('96c37639-6e2f-57d7-86b1-fb719bb95ada', v_en, $J$performance_indicator$J$, $J$Numbers · GB-3.1$J$, $J$Explains, using a real historical example, how a new mathematical idea (e.g. zero, negative numbers, algebra) built on and modified earlier ideas rather than appearing from nothing — an application of the same 'starts from the closest known case, then improves it' pattern oe-interdisciplinary-k12's Strand 204 develops for individual and cultural learning generally.$J$, $J$GB-3$J$, $J$Mathematics$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-numbers-gb3#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-5-numbers.yaml"}}$J$::jsonb, 'draft'),
  ('1a4d5ccb-e4b1-5c24-8ddd-25089cda6bae', v_en, $J$performance_indicator$J$, $J$Numbers · GB-3.2$J$, $J$Takes and defends a position, with reasons, on whether a specific mathematical idea (their own chosen example) was 'discovered' (it was always true, waiting to be found) or 'invented' (people constructed it, and could plausibly have constructed something different) — an explicit, age-appropriate first encounter with a genuine open question in the philosophy of mathematics, not a settled answer this LPM hands them.$J$, $J$GB-3$J$, $J$Mathematics$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-numbers-gb3#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-5-numbers.yaml"}}$J$::jsonb, 'draft'),
  ('b2ddaa27-be03-5b4e-9b6f-5d2ad7a87c32', v_en, $J$performance_indicator$J$, $J$Numbers · GB-3.3$J$, $J$Identifies one way computers or computational tools represent quantity (e.g. binary) as a present-day continuation of the same Great Story, connecting historical number systems to the Computer Models content anchor.$J$, $J$GB-3$J$, $J$Mathematics$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-numbers-gb3#pi3","ordinal":3,"kind":"observable-performance","review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-5-numbers.yaml"}}$J$::jsonb, 'draft'),
  ('03ced9b0-176c-5a55-be28-f301f6d96386', v_en, $J$substrand$J$, $J$Bridge: Beyond Cosmic Education's Own Scope$J$, NULL, $J$GB-4$J$, $J$Mathematics$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-numbers-gb4","typicalGradeBand":"GB-4 (~12–14)","gradeBandId":"GB-4","gradeBandLabel":"Lower Secondary II","approxAge":"12–14","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[{"system":"big-history-project","systemName":"OER Project — Big History Project (Eight Thresholds)","systemType":"state-standards","code":"Threshold 8: The Modern Revolution (touches quantification/measurement history)","note":"Weaker, more indirect match than the others above — the Modern Revolution threshold's own scope is broader than number-systems history specifically, so this mapping is offered as a plausible bridge rather than a close content match.","noteLanguage":"en","confidence":"uncertain","concepts":[],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Draft; no human expert has reviewed it yet."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-5-numbers.yaml"}}$J$::jsonb, 'draft'),
