  INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status) VALUES
  ('3297de0f-689f-5f64-933d-c2ce7b81c54e', v_de, 'concept', $J$Kosmische Aufgabe$J$, $J$Aus Montessoris Pädagogik: Montessoris Aussage, dass jedes Element, jeder Organismus und jede Kraft eine Rolle spielt, die dem Fortbestand der gesamten belebten und physischen Welt dient. Das ist der gefühlsmäßige und ethische Kern der Kosmischen Erziehung; er soll beim Kind ein Gefühl von Sinn und Verantwortung innerhalb eines größeren Ganzen aufbauen.
  INSERT INTO lpm_data_objects (id, project_id, object_type, title, description, grade_band, subject_area, content, status) VALUES
  ('e4479c34-a5d4-500c-b100-845ac6d46014', v_de, $J$strand$J$, $J$Die Geschichte des Universums$J$, $J$Montessoris Erste Große Erzählung: die Entstehung des Universums, des Sonnensystems und der Erde, erzählt als eine dramatische, impressionistische Erzählung — Materie, Energie, Schwerkraft und die sie bestimmenden Gesetze, dargestellt als „großes Bild", bevor ein einzelnes naturwissenschaftliches Fach (Astronomie, Chemie, Physik, Geographie) isoliert behandelt wird. Die Leitidee (Vernetztheit — alles im physikalischen Universum folgt gemeinsamen, erforschbaren Gesetzen) wird in der Unterstufe erzählerisch eingeführt und vertieft sich zu echten erd- und physikwissenschaftlichen Inhalten, sobald Kinder ihren eigenen Fragen durch „Erkundungsgänge" nachgehen.$J$, NULL, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe","sequence":1,"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands; Montessori's own claimed scope is GB-1–GB-3, ~ages 6–12)","associatedDomains":["Science","Geography","Chemistry","Physics"],"relations":{"foundationalTo":["OE-STRAND-cosmic-education-k12-story-of-life"],"parallel":[]},"homeAnchors":[{"id":"computer-models","label":"Computermodelle","description":"Vereinfachte, regelbasierte Simulationen, mit denen sich komplexe reale Systeme nachbilden und untersuchen lassen."},{"id":"our-mind","label":"Unser Geist","description":"Die Werkzeuge des kausalen Denkens auf das eigene Denken, Fühlen und Verhalten anwenden."}],"thinkingTool":{"id":"structure-of-knowledge-diagrams","label":"Wissensstruktur-Diagramme","description":"Eine Hierarchie von Fakten über Konzepte zu Prinzipien, die zeigt, wie viele Einzelheiten mit einer größeren Idee zusammenhängen — dieselbe Beziehung, die eine Große Erzählung zu den detaillierten Fachstudien hat, die sich aus ihr entwickeln."},"essentialQuestion":{"broad":"Woher kommt alles, und warum hält es zusammen?","worked":"Eine einzige Erzählung kann Astronomie, Chemie, Geographie und Physik zusammenhalten, ohne eines dieser Fächer zu verflachen — was verliert und was gewinnt eine Klasse, wenn sie mit einer großen Erzählung statt mit vier getrennten Fächern beginnt?"},"ecosystemConnections":[{"id":"universe-to-big-history","repo":"Big History Project (OER Project, external)","kind":"continues-into","title":"Fortsetzung in: Big History Projects Schwellen 1–4","description":"Strang 1 endet bei etwa 12 Jahren, gemäß Montessoris eigenem Geltungsbereich. Das kostenlose, sekundarstufengerechte Big History Project des OER Project setzt genau in diesem Alter mit derselben Erzählung fort."},{"id":"whole-lpm-to-halle-memo","repo":"deutsche_lp","kind":"continues-into","title":"Setzt um: das Forschungsmemo zur Halle-Kooperation","description":"Dieses gesamte Modell ist der konkrete, laufende erste Schritt, den das Forschungssynthese-Memo vom 11.09.2026 empfohlen hat."}],"review":{"state":"unreviewed","note":"Beschreibung und Leitfragen stammen aus dem zweisprachigen Entwurf."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('e28e6e17-5e02-5dd3-9e7f-444021791ef1', v_de, $J$substrand$J$, $J$Über den Himmel staunen$J$, NULL, $J$GB-0$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb0","typicalGradeBand":"GB-0 (~3–6)","gradeBandId":"GB-0","gradeBandLabel":"Frühe Kindheit","approxAge":"3–6","required":false,"concepts":[],"montessoriScope":"informal-precursor","crosswalks":[{"system":"sachsen-lehrplan","systemName":"Sächsischer Lehrplan Grundschule Sachunterricht","systemType":"state-standards","code":"vor der Schulpflicht","note":"Die Kita liegt vor der Schulpflicht und außerhalb des Geltungsbereichs des Sächsischen Lehrplans — auch die eigene GB-0-Stufe dieses Modells ist ein informeller, nicht Montessori-eigener Vorläufer.","noteLanguage":"de","confidence":"confirmed","concepts":[],"appliesToAllStrands":true}],"review":{"state":"unreviewed","note":"Bezeichnung aus dem Entwurf; Zuordnungen zu Lehrplänen tragen jeweils ihre eigene Sicherheitsangabe."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
  ('9131e7ed-c0d4-5c78-a519-453752ca1e19', v_de, $J$performance_indicator$J$, $J$Universums · GB-0.1$J$, $J$Bemerkt Sonne, Mond und Sterne und stellt Fragen dazu, über unmittelbare Sinneserfahrung (Tag- und Nachtspaziergänge, einfache Himmelsbeobachtung). Es gibt keine inhaltliche Erwartung. Das ist ein informeller Vorläufer, den dieses Modell ergänzt; er gehört nicht zu Montessoris Erster Großer Erzählung.$J$, $J$GB-0$J$, $J$Science$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-the-universe-gb0#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-1-universe.yaml"}}$J$::jsonb, 'draft'),
