  ('2c0b51be-fdb3-5b01-a6fd-6e5e5071f998', v_de, $J$strand$J$, $J$Die Geschichte des Lebens$J$, $J$Montessoris Zweite Große Erzählung: das Erscheinen und die Veränderung des Lebens auf der Erde über geologische Zeiträume hinweg, erzählt anhand der Zeitleiste des Lebens und der Erdzeituhr — Pflanzen und Tiere, die im Paläozoikum, Mesozoikum und Känozoikum erscheinen, sich verändern und oft wieder verschwinden. Hier trifft die affektive Rahmung der „Kosmischen Aufgabe" (jedes Lebewesen erfüllt eine Aufgabe im Dienst des Ganzen) am unmittelbarsten auf die von der Evolutionsbiologie hart erarbeitete Unterscheidung zwischen legitimer und nicht legitimer zweckgerichteter Sprache — dieser Strang benennt diese Spannung in Stufe GB-3 ausdrücklich, statt sie implizit zu lassen.$J$, NULL, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life","sequence":2,"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands; Montessori's own claimed scope is GB-1–GB-3, ~ages 6–12; GB-4+ hands off to oe-interdisciplinary-k12)","associatedDomains":["Biology","Science"],"relations":{"foundationalTo":["OE-STRAND-cosmic-education-k12-story-of-humans"],"parallel":[]},"homeAnchors":[{"id":"cross-species-comparisons","label":"Artenvergleiche","description":"Menschen mit anderen Lebewesen vergleichen, um zu fragen, was gemeinsam und was unterschiedlich ist."},{"id":"ancient-ancestors","label":"Frühe Vorfahren","description":"Die Ur- und Frühgeschichte des Menschen als Quelle für Perspektive auf die Gegenwart."}],"thinkingTool":{"id":"tinbergens-four-questions","label":"Tinbergens vier Fragen","description":"Trennt vier unterschiedliche Erklärungsarten für ein Merkmal oder Verhalten: unmittelbarer Mechanismus, Entwicklung, heutiger Nutzen, evolutionäre Entstehung — hier für Strang 2s Lebensgeschichte am oberen Ende dieser Progression eingesetzt."},"essentialQuestion":{"broad":"Wie hat sich das Leben auf der Erde verändert, und was bedeutet „Veränderung“ über so gewaltige Zeiträume hinweg?","worked":"Montessoris Kosmische Aufgabe sagt, jedes Lebewesen habe eine Rolle im Dienst des Ganzen. Eine Biologin sagt, ein Merkmal bestehe fort, weil es früheren Generationen beim Überleben und Fortpflanzen geholfen hat, nicht weil es gebraucht wurde. Sind das zwei Formulierungen derselben Idee, oder wirklich unterschiedliche Aussagen — und ist es wichtig, welche ein Kind am Ende glaubt?"},"ecosystemConnections":[{"id":"life-to-interdisciplinary-k12","repo":"oe-interdisciplinary-k12","kind":"continues-into","title":"Fortsetzung in: Strang 1 von oe-interdisciplinary-k12 (Vererbung/Variation/Selektion)","description":"Dieses Modell unterrichtet bewusst keine formale natürliche Selektion oder Genetik neu — dieser reale, klassenstufenweise zugeordnete Inhalt existiert bereits als eigene 6-8- und 9-12-Stufe von oe-interdisciplinary-k12."},{"id":"life-teleology-tension","repo":"theorybase","kind":"names-tension-with","title":"Benennt eine reale Spannung mit: der Selektions-Teleologie-Proposition von theorybase","description":"Die GB-3-Stufe von Strang 2 ist die einzige Stelle in diesem Modell, an der Montessoris eigene „Kosmische Aufgabe“-Rahmung direkt neben die reale, dokumentierte Position dieses Ökosystems zu legitimer und nicht legitimer zweckgerichteter Sprache gestellt wird."}],"review":{"state":"unreviewed","note":"Beschreibung und Leitfragen stammen aus dem zweisprachigen Entwurf."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('03f6f050-90ce-54ad-b85f-3fbe321cf009', v_de, $J$substrand$J$, $J$Lebendiges und Unbelebtes wahrnehmen$J$, NULL, $J$GB-0$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb0","typicalGradeBand":"GB-0 (~3–6)","gradeBandId":"GB-0","gradeBandLabel":"Frühe Kindheit","approxAge":"3–6","required":false,"concepts":[],"montessoriScope":"informal-precursor","crosswalks":[{"system":"sachsen-lehrplan","systemName":"Sächsischer Lehrplan Grundschule Sachunterricht","systemType":"state-standards","code":"vor der Schulpflicht","note":"Die Kita liegt vor der Schulpflicht und außerhalb des Geltungsbereichs des Sächsischen Lehrplans — auch die eigene GB-0-Stufe dieses Modells ist ein informeller, nicht Montessori-eigener Vorläufer.","noteLanguage":"de","confidence":"confirmed","concepts":[],"appliesToAllStrands":true}],"review":{"state":"unreviewed","note":"Bezeichnung aus dem Entwurf; Zuordnungen zu Lehrplänen tragen jeweils ihre eigene Sicherheitsangabe."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('c95cf894-78f1-54f5-902f-b512da754935', v_de, $J$performance_indicator$J$, $J$Lebens · GB-0.1$J$, $J$Sortiert vertraute Gegenstände über unmittelbare Sinneserfahrung in belebt und unbelebt. Es gibt keine inhaltliche Erwartung. Das ist ein informeller Vorläufer, den dieses Modell ergänzt; er gehört nicht zu Montessoris Zweiter Großer Erzählung.$J$, $J$GB-0$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb0#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('37a0df24-9f7c-5554-aea4-2b8597922440', v_de, $J$substrand$J$, $J$Die Zeitleiste des Lebens, erstes Erzählen$J$, $J$Schlüsselkonzepte: Große Erzählung, Zeitleisten-Denken, Kosmische Aufgabe$J$, $J$GB-1$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb1","typicalGradeBand":"GB-1 (~6–8)","gradeBandId":"GB-1","gradeBandLabel":"Primarstufe I","approxAge":"6–8","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-great-story","emphasis":"reinforcing"},{"id":"OE-CONCEPT-cosmic-k12-timeline-reasoning","emphasis":"primary"},{"id":"OE-CONCEPT-cosmic-k12-cosmic-task","emphasis":"primary"}],"montessoriScope":"inside","crosswalks":[{"system":"montessori-tradition","systemName":"Montessori Kosmische Erziehung (eigene Tradition)","systemType":"pedagogical-tradition","code":"Second Great Lesson: 'The Coming of Life' — first telling","note":"Bestätigte, benannte Erzählung und ihr erstes Erzählen, meist im Anschluss an die Erste Große Erzählung im selben Trimester.","noteLanguage":"de","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-timeline-reasoning"],"appliesToAllStrands":false},{"system":"sachsen-lehrplan","systemName":"Sächsischer Lehrplan Grundschule Sachunterricht","systemType":"state-standards","code":"LB 3: Begegnungen mit Pflanzen und Tieren (45 Ustd., Kl. 1/2)","note":"Der größte einzelne Lernbereich dieser Klassenstufe (45 von rund 130 Gesamtstunden) — eine reale, substanzielle Heimat für die frühen Pflanzen-/Tierinhalte von Strang 2, ohne dass die Quelle selbst auf Montessori oder eine Zeitleisten-Rahmung Bezug nimmt.","noteLanguage":"de","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-timeline-reasoning","OE-CONCEPT-cosmic-k12-cosmic-task"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Bezeichnung aus dem Entwurf; Zuordnungen zu Lehrplänen tragen jeweils ihre eigene Sicherheitsangabe."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('fcff11a4-2ea8-563d-ac02-e650f48bafd3', v_de, $J$performance_indicator$J$, $J$Lebens · GB-1.1$J$, $J$Hört mit Hilfe der Zeitleiste des Lebens (oder einer gleichwertigen Darstellung) die Erzählung, in welcher Reihenfolge die großen Lebensformen erschienen sind, und gibt sie wieder. Förmliche Namen der Erdzeitalter sind noch nicht nötig.$J$, $J$GB-1$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb1#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('e8f0c810-9022-50bd-b329-ffff909b207c', v_de, $J$performance_indicator$J$, $J$Lebens · GB-1.2$J$, $J$Nennt eine einfache Art, wie ein Lebewesen einem anderen Lebewesen oder seiner Umgebung hilft (z. B. eine Pflanze erzeugt Sauerstoff, ein Wurm lockert den Boden). Das ist ein früher, gefühlsnaher, kindgerechter Einstieg in die Idee der Kosmischen Aufgabe und ausdrücklich noch keine förmliche biologische Behauptung.$J$, $J$GB-1$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb1#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('a0440ed2-ded1-5209-86a5-f907d955e7cd', v_de, $J$performance_indicator$J$, $J$Lebens · GB-1.3$J$, $J$Auf dieser Stufe nicht behandelt: formale Genetik, die Mechanik der natürlichen Selektion oder die Begriffe Variation, Selektion und Vererbung. Dieser Wortschatz gehört in die K-2-Stufe von oe-interdisciplinary-k12. Diese Teilstufe bleibt auf der Ebene der eindrucksvollen Erzählung, mit der auch Montessoris Elementarstufe beginnt.$J$, $J$GB-1$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb1#pi3","ordinal":3,"kind":"scope-note","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('84164130-930a-5d66-889d-c9465e350aaf', v_de, $J$substrand$J$, $J$Die Erdzeituhr und Erkundungsgänge in die Biologie$J$, $J$Schlüsselkonzepte: Zeitleisten-Denken, Erkundungsgang$J$, $J$GB-2$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb2","typicalGradeBand":"GB-2 (~8–10)","gradeBandId":"GB-2","gradeBandLabel":"Primarstufe II","approxAge":"8–10","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-timeline-reasoning","emphasis":"reinforcing"},{"id":"OE-CONCEPT-cosmic-k12-going-out","emphasis":"primary"}],"montessoriScope":"inside","crosswalks":[{"system":"ib-pyp","systemName":"IB Primary Years Programme — Sechs transdisziplinäre Themen","systemType":"state-standards","code":"How the World Works","note":"Bestätigte Themenbezeichnung; die Lebensgeschichte-Inhalte von Strang 2 fallen unter dasselbe PYP-Thema wie Strang 1.","noteLanguage":"de","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-timeline-reasoning"],"appliesToAllStrands":false},{"system":"montessori-tradition","systemName":"Montessori Kosmische Erziehung (eigene Tradition)","systemType":"pedagogical-tradition","code":"Timeline of Life; Clock of Eras; the Long Black Line","note":"Bestätigte, benannte Materialien: die Zeitleiste des Lebens zeigt Paläozoikum, Mesozoikum und Känozoikum; die Erdzeituhr ist eine proportionale Visualisierung geologischer Zeit; die Lange Schwarze Linie stellt die gesamte Erdgeschichte in einem Maßstab dar, der die menschliche Existenz im Vergleich visuell verschwindend klein erscheinen lässt.","noteLanguage":"de","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-timeline-reasoning"],"appliesToAllStrands":false},{"system":"sachsen-anhalt-lehrplan","systemName":"Fachlehrplan Grundschule Sachunterricht (Sachsen-Anhalt)","systemType":"state-standards","code":"Naturwissenschaftlicher Bereich, Schuljahrgang 2 und 4: 'Pflanzen und Tiere'","note":"Bestätigt: die Kompetenzen am Ende von Schuljahrgang 4 verlangen ausdrücklich das Erfassen 'grundlegende[r] Zusammenhänge zwischen der lebenden und nicht lebenden Natur' — die eigenen Worte des Lehrplans für genau die Vernetztheits-Inhalte von Strang 2.","noteLanguage":"de","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-going-out"],"appliesToAllStrands":false},{"system":"thueringen-lehrplan","systemName":"Thüringer Lehrplan Heimat- und Sachkunde","systemType":"state-standards","code":"Lernbereich: Lebewesen und Lebensräume","note":"„Lebewesen und Lebensräume“ entspricht dem Namen nach direkt den Inhalten von Strang 2; die vom Thüringer Schulportal selbst genannten Beispielthemen umfassen Wetter, Sterne und Planeten sowie Sinnesorgane.","noteLanguage":"de","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-interconnectedness"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Bezeichnung aus dem Entwurf; Zuordnungen zu Lehrplänen tragen jeweils ihre eigene Sicherheitsangabe."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('03594f2f-f1ee-5791-a1ac-b28eb5fada51', v_de, $J$performance_indicator$J$, $J$Lebens · GB-2.1$J$, $J$Nutzt die Erdzeituhr (oder eine gleichwertige maßstäbliche Darstellung der Tiefenzeit), um zu vergleichen, wie lange verschiedene Lebensformen schon existieren, z. B. wie klein der Anteil der Uhr ist, den die gesamte Existenz des Menschen einnimmt.$J$, $J$GB-2$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb2#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('d69a19f9-1e70-590e-9872-5bde3a3112e3', v_de, $J$performance_indicator$J$, $J$Lebens · GB-2.2$J$, $J$Plant und führt einen selbstgesteuerten Erkundungsgang zu einer ausgestorbenen oder lebenden Organismengruppe durch, auf die die Zeitleiste des Lebens neugierig gemacht hat.$J$, $J$GB-2$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb2#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('5adb54f4-6d69-5276-a33d-5de8be8dfd85', v_de, $J$performance_indicator$J$, $J$Lebens · GB-2.3$J$, $J$Ordnet Lebewesen mit einem einfachen System (z. B. Gruppen auf der Ebene der Reiche) und versteht das als greifbaren Beleg dafür, dass die Vielfalt des Lebens eine Ordnung hat. So wird die Erzählung an die heute beobachtbare Biologie zurückgebunden.$J$, $J$GB-2$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb2#pi3","ordinal":3,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('93a79dd7-9354-590f-a63b-f6819c159ee9', v_de, $J$substrand$J$, $J$Eine Aufgabe oder eine Folge? Die Spannung benennen$J$, $J$Schlüsselkonzepte: Kosmische Aufgabe, Evolutionärer Prozess$J$, $J$GB-3$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb3","typicalGradeBand":"GB-3 (~10–12)","gradeBandId":"GB-3","gradeBandLabel":"Sekundarstufe I (früh)","approxAge":"10–12","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-cosmic-task","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-evolutionary-process","emphasis":"reinforcing"}],"montessoriScope":"inside","crosswalks":[{"system":"montessori-tradition","systemName":"Montessori Kosmische Erziehung (eigene Tradition)","systemType":"pedagogical-tradition","code":"Upper Elementary deepening: Cosmic Task discussions, biome/ecosystem research","note":"Die dokumentierte Vertiefung der Oberstufe der Kosmische-Aufgabe-Inhalte in ausdrücklichere Diskussionen ökologischer Rollen — genau das Material, in dem die eigene GB-3-Stufe dieses Modells die Teleologie-Spannung benennt.","noteLanguage":"de","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-cosmic-task"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Bezeichnung aus dem Entwurf; Zuordnungen zu Lehrplänen tragen jeweils ihre eigene Sicherheitsangabe."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('9e76c887-16a0-5ee4-b621-d46ca6eba082', v_de, $J$performance_indicator$J$, $J$Lebens · GB-3.1$J$, $J$Erklärt mit eigenen Worten sowohl die Darstellung der Kosmischen Aufgabe, warum ein Merkmal existiert (es erfüllt eine Rolle, die das Gesamtsystem braucht), als auch eine selektionsbasierte Darstellung (es blieb erhalten, weil es früheren Individuen half, öfter zu überleben und sich fortzupflanzen als Alternativen) für dasselbe echte Beispiel (z. B. Schnabelform eines Vogels, Dornen einer Pflanze).$J$, $J$GB-3$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb3#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('190b4dfc-6f49-5883-bb0c-f0aa31cabe93', v_de, $J$performance_indicator$J$, $J$Lebens · GB-3.2$J$, $J$Erkennt bei zwei Sätzen über dasselbe Merkmal, welcher Satz beschreibt, was das Merkmal jetzt tut (seine heutige Rolle) und welcher, warum es historisch entstanden ist (seine Selektionsgeschichte). Das ist der altersgerechte Zugang zur zentralen Forschungsfrage dieses Modells, wie die Sprache der Kosmischen Aufgabe im Denken von Kindern tatsächlich ankommt.$J$, $J$GB-3$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb3#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('0569d5f0-7832-5c49-b738-9a37bf9b6117', v_de, $J$performance_indicator$J$, $J$Lebens · GB-3.3$J$, $J$Wendet Tinbergens vier Fragen (Mechanismus, Entwicklung, Funktion, evolutionärer Ursprung) auf ein Beispiel aus der Zeitleiste des Lebens an und trennt dabei ausdrücklich „Was tut es?“ von „Warum hat es sich entwickelt?“ als zwei verschiedene, beide berechtigte Fragen und nicht als eine Frage mit einer Antwort.$J$, $J$GB-3$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb3#pi3","ordinal":3,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('44e99bde-f9ff-5761-ba3c-9dbce4cad94d', v_de, $J$substrand$J$, $J$Übergabe: Formale Evolutionsbiologie$J$, NULL, $J$GB-4$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb4","typicalGradeBand":"GB-4 (~12–14)","gradeBandId":"GB-4","gradeBandLabel":"Sekundarstufe I (spät)","approxAge":"12–14","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[{"system":"big-history-project","systemName":"OER Project — Big History Project (Acht Schwellen)","systemType":"state-standards","code":"Threshold 5: Life on Earth","note":"Bestätigter Schwellenname und Position — die natürliche Fortsetzung für Strang 2 nach dem 12. Lebensjahr.","noteLanguage":"de","confidence":"confirmed","concepts":[],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Bezeichnung aus dem Entwurf; Zuordnungen zu Lehrplänen tragen jeweils ihre eigene Sicherheitsangabe."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('021b8b46-367f-543d-a8c6-5cff5392881d', v_de, $J$performance_indicator$J$, $J$Lebens · GB-4.1$J$, $J$Dieses Modell unterrichtet formale natürliche Selektion, Genetik und Vererbungsmechanik hier bewusst nicht neu. Diese Inhalte gibt es bereits, klassenstufenweise zugeordnet, als Strang 1 (Vererbung, Variation, Selektion) in den Stufen 6-8 und 9-12 von oe-interdisciplinary-k12 und in der parallelen Behandlung von bio-core-k12. Wer eine auf Kosmischer Erziehung aufbauende Sequenz über das Alter von 12 hinaus fortsetzt, sollte direkt an eines dieser beiden Modelle übergeben und hier keine doppelten Inhalte erwarten.$J$, $J$GB-4$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb4#pi1","ordinal":1,"kind":"handoff-note","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
