  ('8899b768-12e6-54a8-8874-5727bc6c2358', v_de, $J$substrand$J$, $J$Brücke: Jenseits der Kosmischen Erziehung$J$, NULL, $J$GB-6$J$, $J$Biology$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-life-gb6","typicalGradeBand":"GB-6 (~16–19)","gradeBandId":"GB-6","gradeBandLabel":"Sekundarstufe II (spät)","approxAge":"16–19","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[],"review":{"state":"unreviewed","note":"Bezeichnung aus dem Entwurf; Zuordnungen zu Lehrplänen tragen jeweils ihre eigene Sicherheitsangabe."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-2-life.yaml"}}$J$::jsonb, 'draft'),
  ('aaa0daea-2e68-5d6e-9ae1-e34c512990a7', v_de, $J$strand$J$, $J$Die Geschichte des Menschen$J$, $J$Montessoris Dritte Große Erzählung: das Erscheinen des Menschen, die Zeitleiste der Hominiden und — ihr eigenes, namentlich benanntes Ordnungsprinzip — die Grundbedürfnisse des Menschen (physisch: Nahrung, Unterkunft, Verteidigung, Transport; geistig-seelisch: Kunst, Religion, Musik, ein Gefühl von Bedeutsamkeit), die jede menschliche Kultur zu jeder Epoche auf unterschiedliche Weise erfüllt hat. Der Strang, in dem die eigene kulturübergreifende Rahmung der Kosmischen Erziehung — ein Bedürfnis, viele gültige Lösungen — strukturell parallel zur eigenen Behandlung universeller menschlicher Bedürfnisse und variabler kultureller Lösungen in der Evolutionären Anthropologie verläuft.$J$, NULL, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans","sequence":3,"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands; Montessori's own claimed scope is GB-1–GB-3, ~ages 6–12)","associatedDomains":["History","Social Studies","Ethics/Religion","Geography"],"relations":{"foundationalTo":["OE-STRAND-cosmic-education-k12-story-of-language","OE-STRAND-cosmic-education-k12-story-of-numbers"],"parallel":[]},"homeAnchors":[{"id":"ancient-ancestors","label":"Frühe Vorfahren","description":"Die Ur- und Frühgeschichte des Menschen als Quelle für Perspektive auf die Gegenwart."},{"id":"cultural-diversity","label":"Kulturelle Vielfalt","description":"Wie unterschiedliche menschliche Gruppen dieselben Grundbedürfnisse unterschiedlich lösen."},{"id":"cooperation-games","label":"Kooperationsspiele","description":"Einfache Strukturen, mit denen sich untersuchen lässt, wann sich Kooperation für eine Gruppe lohnt."}],"thinkingTool":{"id":"payoff-matrices","label":"Nutzenmatrizen","description":"Tabellen, die Kosten und Nutzen verschiedener Entscheidungen für verschiedene Akteure gegenüberstellen — hier eingesetzt, wo sich Strang 3 der Kooperation und Arbeitsteilung zuwendet."},"essentialQuestion":{"broad":"Was brauchen alle Menschen, und wie unterschiedlich haben Menschen dieselben Bedürfnisse erfüllt?","worked":"Jede bekannte menschliche Gruppe musste dieselbe Handvoll Probleme lösen — Nahrung, Unterkunft, Sicherheit, Sinn. Eine Klasse, die vergleicht, wie drei sehr unterschiedliche Kulturen „Unterkunft“ gelöst haben, tut etwas, das die Evolutionäre Anthropologie auch mit „Kooperation“ oder „Fairness“ tut — was ändert sich, und was bleibt gleich, wenn dieselbe vergleichende Methode auf ein physisches statt ein soziales Bedürfnis angewendet wird?"},"ecosystemConnections":[{"id":"humans-to-eva-buch","repo":"eva_buch","kind":"structural-parallel","title":"Strukturelle Parallele: eva_buchs Evolutionäre Anthropologie als fächerübergreifendes Rückgrat","description":"Susan Hanischs kommendes Springer-Buch behandelt Evolutionäre Anthropologie als fächerübergreifendes Rückgrat für Sozialkunde-, Ethik/Philosophie-, Geschichte- und Psychologie-Lehrpläne aller deutschen Bundesländer."},{"id":"humans-to-osci-timeline","repo":"oSci","kind":"draws-on","title":"Stützt sich auf: oScis seitenverifizierte Zeitleiste prähistorischer Technik","description":"Die data/timeline/-Einträge von oSci (Feuerkontrolle, Acheuléen-Faustkeile, früheste Levallois-Steinwerkzeuge, Kunst/Perlen) sind reale, seitenverifizierte Extraktion aus Feist (2006)."}],"review":{"state":"unreviewed","note":"Beschreibung und Leitfragen stammen aus dem zweisprachigen Entwurf."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('a85b591c-4f78-508d-ab37-5a39e05c58e4', v_de, $J$substrand$J$, $J$Wahrnehmen, was Menschen brauchen$J$, NULL, $J$GB-0$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb0","typicalGradeBand":"GB-0 (~3–6)","gradeBandId":"GB-0","gradeBandLabel":"Frühe Kindheit","approxAge":"3–6","required":false,"concepts":[],"montessoriScope":"informal-precursor","crosswalks":[{"system":"sachsen-lehrplan","systemName":"Sächsischer Lehrplan Grundschule Sachunterricht","systemType":"state-standards","code":"vor der Schulpflicht","note":"Die Kita liegt vor der Schulpflicht und außerhalb des Geltungsbereichs des Sächsischen Lehrplans — auch die eigene GB-0-Stufe dieses Modells ist ein informeller, nicht Montessori-eigener Vorläufer.","noteLanguage":"de","confidence":"confirmed","concepts":[],"appliesToAllStrands":true}],"review":{"state":"unreviewed","note":"Bezeichnung aus dem Entwurf; Zuordnungen zu Lehrplänen tragen jeweils ihre eigene Sicherheitsangabe."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('0af5df4a-59cc-5892-b05b-93e80209dfcc', v_de, $J$performance_indicator$J$, $J$Menschen · GB-0.1$J$, $J$Nennt Grundbedürfnisse (Essen, ein sicherer Schlafplatz) aus der eigenen Erfahrung. Es gibt keine inhaltliche Erwartung. Das ist ein informeller Vorläufer, den dieses Modell ergänzt; er gehört nicht zu Montessoris Dritter Großer Erzählung.$J$, $J$GB-0$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb0#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('9744c519-f4b5-5797-857f-d2eed38dcaa9', v_de, $J$substrand$J$, $J$Das Erscheinen des Menschen, erstes Erzählen$J$, $J$Schlüsselkonzepte: Große Erzählung, Grundbedürfnisse des Menschen$J$, $J$GB-1$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb1","typicalGradeBand":"GB-1 (~6–8)","gradeBandId":"GB-1","gradeBandLabel":"Primarstufe I","approxAge":"6–8","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-great-story","emphasis":"reinforcing"},{"id":"OE-CONCEPT-cosmic-k12-fundamental-human-needs","emphasis":"primary"}],"montessoriScope":"inside","crosswalks":[{"system":"montessori-tradition","systemName":"Montessori Kosmische Erziehung (eigene Tradition)","systemType":"pedagogical-tradition","code":"Third Great Lesson: 'The Coming of Humans' — Fundamental Needs Chart","note":"Bestätigte, benannte Erzählung und ihr eigenes benanntes Anschlussmaterial: die Zeitleiste der Menschheitsgeschichte und die Grundbedürfnisse-der-Menschen-Tafel.","noteLanguage":"de","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-fundamental-human-needs"],"appliesToAllStrands":false},{"system":"sachsen-anhalt-lehrplan","systemName":"Fachlehrplan Grundschule Sachunterricht (Sachsen-Anhalt)","systemType":"state-standards","code":"Erkunden (Prozesskompetenz, Endniveau Schuljahrgang 4)","note":"Die Prozesskompetenz „Erkunden“ wird als Untersuchen von Ungeklärtem aus der kindlichen Lebenswirklichkeit mit Arbeitsgeräten und Medien definiert — dieselbe selbstgesteuerte Erkundungshaltung, die auch der Erkundungsgang-Begriff dieses Modells benennt.","noteLanguage":"de","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-fundamental-human-needs"],"appliesToAllStrands":false},{"system":"sachsen-lehrplan","systemName":"Sächsischer Lehrplan Grundschule Sachunterricht","systemType":"state-standards","code":"LB 2: Mein Körper und meine Gesundheit (20 Ustd., Kl. 1/2)","note":"Körper- und Gesundheitsinhalte sind der eigene Einstiegspunkt des sächsischen Lehrplans für die körperlichen Grundbedürfnisse eines Kindes.","noteLanguage":"de","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-fundamental-human-needs"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Bezeichnung aus dem Entwurf; Zuordnungen zu Lehrplänen tragen jeweils ihre eigene Sicherheitsangabe."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('9cffc428-0232-5cbc-967a-28c9d8276949', v_de, $J$performance_indicator$J$, $J$Menschen · GB-1.1$J$, $J$Hört die Erzählung vom Erscheinen des Menschen auf der Zeitleiste des Lebens, nach der viel längeren Zeitspanne aus Strang 2, und gibt sie wieder.$J$, $J$GB-1$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb1#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('6b06e800-c370-5ce8-a9d1-2f95f2c31c7d', v_de, $J$performance_indicator$J$, $J$Menschen · GB-1.2$J$, $J$Nennt mindestens zwei körperliche Bedürfnisse (Nahrung, Unterkunft) und mindestens ein seelisches Bedürfnis (z. B. etwas Schönes schaffen wollen, zu einer Gruppe gehören wollen), das jeder Mensch hat. Das ist ein früher, gefühlsnaher Einstieg in die Grundbedürfnisse.$J$, $J$GB-1$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb1#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
