  ('0cb2c8e2-10a8-5a9a-a4ac-afe1a057fb89', v_de, $J$performance_indicator$J$, $J$Menschen · GB-2.1$J$, $J$Vergleicht die Lösungen von mindestens drei Kulturen oder Zeitepochen für dasselbe körperliche Bedürfnis (z. B. Unterkunft: Iglu, Jurte, Langhaus) und benennt, was am zugrunde liegenden Bedürfnis gemeinsam ist und was an der Lösung wirklich verschieden. Das ist die kindgerechte Form der Lesart dieses Ökosystems von der evolutionären Anthropologie: ein Bedürfnis, viele kulturell verschiedene Lösungen.$J$, $J$GB-2$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb2#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('ca460271-7fad-5d88-a5dc-398abfa9e1a7', v_de, $J$performance_indicator$J$, $J$Menschen · GB-2.2$J$, $J$Beschreibt einen konkreten Beleg für frühe menschliche Technik (z. B. Feuerbeherrschung, frühe Steinwerkzeuge) als tatsächliche historische Leistung, nicht als Mythos oder Vermutung. Dabei wird, wo vorhanden, die seitenverifizierte Materialsammlung zur vorgeschichtlichen Technik (oScis Auszug) genutzt.$J$, $J$GB-2$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb2#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('a9e9e742-4371-5a22-8bcd-7089fbb0dc86', v_de, $J$performance_indicator$J$, $J$Menschen · GB-2.3$J$, $J$Plant und führt einen selbstgesteuerten Erkundungsgang durch, der vergleicht, wie ein bestimmtes Bedürfnis in zwei vom Kind selbst gewählten Kulturen erfüllt wurde.$J$, $J$GB-2$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb2#pi3","ordinal":3,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('ab8b3adf-ab34-5656-a1cb-3935d49a2b42', v_de, $J$substrand$J$, $J$Bedürfnisse, Kooperation und Fairness$J$, $J$Schlüsselkonzepte: Grundbedürfnisse des Menschen, Kultur$J$, $J$GB-3$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb3","typicalGradeBand":"GB-3 (~10–12)","gradeBandId":"GB-3","gradeBandLabel":"Sekundarstufe I (früh)","approxAge":"10–12","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-fundamental-human-needs","emphasis":"reinforcing"},{"id":"OE-CONCEPT-oe-interdisciplinary-culture","emphasis":"reinforcing"}],"montessoriScope":"inside","crosswalks":[{"system":"gdsu-perspektivrahmen","systemName":"Perspektivrahmen Sachunterricht (GDSU)","systemType":"national-framework","code":"Historische Perspektive; PVT: Frieden, Demokratie","note":"Abgeleitete Perspektivbezeichnung; die bestätigten, aktuellen PVTs „Frieden“ und „Demokratie“ passen stark zu den Inhalten von Strang 3 gegen Ethnozentrismus in GB-3 und werden im Leitartikel des GDSU-Journals 2026 selbst als „aktuell besonders notwendig“ bezeichnet.","noteLanguage":"de","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-fundamental-human-needs"],"appliesToAllStrands":false},{"system":"sachsen-anhalt-lehrplan","systemName":"Fachlehrplan Grundschule Sachunterricht (Sachsen-Anhalt)","systemType":"state-standards","code":"Historischer Bereich, Schuljahrgang 4: 'Veränderung und Entwicklung des Handelns der Menschen in vergangenen und gegenwärtigen Situationen'","note":"Bestätigt, und eine starke Übereinstimmung: die Kompetenz des Historischen Bereichs am Ende von Schuljahrgang 4 verlangt ausdrücklich den Vergleich heutigen und vergangenen menschlichen Handelns.","noteLanguage":"de","confidence":"confirmed","concepts":["OE-CONCEPT-cosmic-k12-fundamental-human-needs","OE-CONCEPT-cosmic-k12-cultural-diversity-of-solutions"],"appliesToAllStrands":false},{"system":"sachsen-lehrplan","systemName":"Sächsischer Lehrplan Grundschule Sachunterricht","systemType":"state-standards","code":"LB 1: Zusammen leben und lernen (12 Ustd., Kl. 4); Wahlbereich 'Schlösser, Burgen und Gärten in Sachsen'","note":"Die mit 12 Stunden größte Lernbereich-1-Zuteilung aller Klassenstufen sowie ein benannter regionalgeschichtlicher Wahlbereich bieten realen Raum für die Kultur-/Kooperationsinhalte von Strang 3 in dieser Stufe.","noteLanguage":"de","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-fundamental-human-needs","OE-CONCEPT-oe-interdisciplinary-culture"],"appliesToAllStrands":false},{"system":"thueringen-lehrplan","systemName":"Thüringer Lehrplan Heimat- und Sachkunde","systemType":"state-standards","code":"Lernbereich: Natur und Technik","note":"„Natur und Technik“ ist dem Namen nach die plausibelste thüringische Anknüpfung für die Technik- und Bedürfnisinhalte von Strang 3 — echt unsicher, bis eine funktionierende Volltextauswertung des Lehrplans vorliegt.","noteLanguage":"de","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-fundamental-human-needs"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Bezeichnung aus dem Entwurf; Zuordnungen zu Lehrplänen tragen jeweils ihre eigene Sicherheitsangabe."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('7d0da77a-d32d-5f42-a958-37c3171ce668', v_de, $J$performance_indicator$J$, $J$Menschen · GB-3.1$J$, $J$Erklärt mit einem Vergleich im Stil einer Auszahlungsmatrix, warum Gruppen, die ein gemeinsames Bedürfnis erfüllen (z. B. Verteidigung, Nahrungsproduktion im großen Maßstab), oft zusammenarbeiten mussten, um erfolgreich zu sein, und nennt mindestens ein historisches oder heutiges Beispiel.$J$, $J$GB-3$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb3#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('dc16274d-bc06-5d04-be93-d875f39f65d5', v_de, $J$performance_indicator$J$, $J$Menschen · GB-3.2$J$, $J$Unterscheidet an einem echten Beispiel ein Bedürfnis (allgemein, alle Menschen teilen es) von einer Lösung (kulturell verschieden, historisch bestimmt) und erklärt, warum das Vermischen beider dazu führen kann, die Lösung einer Kultur für die einzig richtige zu halten. Das ist ausdrücklich ein Indikator gegen Ethnozentrismus und passt zu den Anliegen von Rassismuskritik und Vorurteilsbewusstsein im Sachunterricht (GDSU Journal 2026, Warburg & Seifert).$J$, $J$GB-3$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb3#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('afddcbb4-865e-5ffc-8035-2adfb54f762e', v_de, $J$performance_indicator$J$, $J$Menschen · GB-3.3$J$, $J$Benennt eine offene historische oder anthropologische Frage zum frühen menschlichen Leben, die noch erforscht wird, und unterscheidet gut belegte Aussagen von offenen Fragen.$J$, $J$GB-3$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb3#pi3","ordinal":3,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('dbe14ca6-ac57-5892-a74f-21ffe57dd7b1', v_de, $J$substrand$J$, $J$Brücke: Evolutionäre Anthropologie im Fächerkanon$J$, NULL, $J$GB-4$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb4","typicalGradeBand":"GB-4 (~12–14)","gradeBandId":"GB-4","gradeBandLabel":"Sekundarstufe I (spät)","approxAge":"12–14","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[{"system":"big-history-project","systemName":"OER Project — Big History Project (Acht Schwellen)","systemType":"state-standards","code":"Thresholds 6-7: Collective Learning; Agriculture","note":"Bestätigte Schwellennamen — „Collective Learning“ (kollektives Lernen) ist die eigene Bezeichnung des Big History Project für im Wesentlichen dasselbe Phänomen, das auch die Grundbedürfnisse-Inhalte von Strang 3 und die evolutionär-anthropologische Rahmung von eva_buch als zentral behandeln.","noteLanguage":"de","confidence":"confirmed","concepts":[],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Bezeichnung aus dem Entwurf; Zuordnungen zu Lehrplänen tragen jeweils ihre eigene Sicherheitsangabe."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('b0d98235-df16-5b23-a0b1-61b062cc3e70', v_de, $J$performance_indicator$J$, $J$Menschen · GB-4.1$J$, $J$Dieses Modell führt die Grundbedürfnisse hier bewusst nicht in einen formalen evolutionär-anthropologischen Unterricht der Sekundarstufe weiter. Das ist genau das Thema von eva_buch (Hanisch, erscheint 2027 bei Springer), gedacht für Biologie, Ethik/Philosophie, Sozialkunde, Geschichte und Psychologie in der Sekundarstufe. Wer eine auf Kosmischer Erziehung aufbauende Sequenz über das Alter von 12 hinaus fortsetzt, sollte auf dieses Buch und die zugehörige Lehrplananalyse-App zurückgreifen und hier keine doppelten Inhalte erwarten.$J$, $J$GB-4$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb4#pi1","ordinal":1,"kind":"handoff-note","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
