  ('2c4aefb4-0345-5c0d-ba69-87e46399430a', v_de, $J$substrand$J$, $J$Brücke: Jenseits der Kosmischen Erziehung$J$, NULL, $J$GB-6$J$, $J$History$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-humans-gb6","typicalGradeBand":"GB-6 (~16–19)","gradeBandId":"GB-6","gradeBandLabel":"Sekundarstufe II (spät)","approxAge":"16–19","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[],"review":{"state":"unreviewed","note":"Bezeichnung aus dem Entwurf; Zuordnungen zu Lehrplänen tragen jeweils ihre eigene Sicherheitsangabe."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-3-humans.yaml"}}$J$::jsonb, 'draft'),
  ('c2bfed36-f572-5cd4-99a9-e511e4144cdf', v_de, $J$strand$J$, $J$Die Geschichte der Sprache$J$, $J$Montessoris Vierte Große Erzählung: wie Menschen dazu kamen, Laute und Ideen durch willkürliche Zeichen darzustellen — Zeichen, Bildschrift, Alphabete — und wie diese eine Erfindung es ermöglichte, Wissen über Generationen hinweg anzuhäufen und weiterzugeben, über das hinaus, was das Gedächtnis allein tragen konnte.$J$, NULL, $J$Language Arts$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-language","sequence":4,"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands; Montessori's own claimed scope is GB-1–GB-3, ~ages 6–12)","associatedDomains":["Language Arts","History","Social Studies"],"relations":{"parallel":["OE-STRAND-cosmic-education-k12-story-of-numbers"]},"homeAnchors":[{"id":"ancient-ancestors","label":"Frühe Vorfahren","description":"Die Ur- und Frühgeschichte des Menschen als Quelle für Perspektive auf die Gegenwart."},{"id":"cultural-diversity","label":"Kulturelle Vielfalt","description":"Wie unterschiedliche menschliche Gruppen dieselben Grundbedürfnisse unterschiedlich lösen."}],"thinkingTool":{"id":"analogy-mapping","label":"Analogien & Analogie-Mapping","description":"Strukturierter, merkmalsweiser Vergleich, der benennt, was sich entspricht und was nicht — hier überall dort eingesetzt, wo sich das Muster einer Großen Erzählung in einer anderen wiederholt."},"essentialQuestion":{"broad":"Wie kamen Zeichen auf einer Oberfläche dazu, Bedeutung zu tragen, und was änderte sich, sobald sie es konnten?","worked":"Jedes Schriftsystem, das Menschen je erfunden haben, nutzt willkürliche, gemeinsam vereinbarte Zeichen — nichts an der Form des Buchstabens „A“ macht seine Bedeutung selbstverständlich. Was gewinnt eine Klasse, wenn sie mehrere echte Schriftsysteme nebeneinander vergleicht, statt das eigene als natürlich oder selbstverständlich zu behandeln?"},"ecosystemConnections":[{"id":"language-to-strand-204","repo":"oe-interdisciplinary-k12","kind":"structural-parallel","title":"Strukturelle Parallele: Strang 204 von oe-interdisciplinary-k12 (Analogie, Suche und das Wachstum des Verstehens)","description":"Strang 204 behandelt einen gemeinsamen, erinnerten Lösungsvorrat als das, was jedes neue Problem leichter lösbar macht — auf jeder Ebene, von einzelnen Köpfen bis zu ganzen Wissenschaftsfeldern."}],"review":{"state":"unreviewed","note":"Beschreibung und Leitfragen stammen aus dem zweisprachigen Entwurf."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-4-language.yaml"}}$J$::jsonb, 'draft'),
