  ('a21bc84c-3679-5d89-b69a-3273d12f29c1', v_de, $J$substrand$J$, $J$Brücke: Jenseits der Kosmischen Erziehung$J$, NULL, $J$GB-6$J$, $J$Language Arts$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-language-gb6","typicalGradeBand":"GB-6 (~16–19)","gradeBandId":"GB-6","gradeBandLabel":"Sekundarstufe II (spät)","approxAge":"16–19","required":false,"concepts":[],"montessoriScope":"handoff-or-bridge","crosswalks":[],"review":{"state":"unreviewed","note":"Bezeichnung aus dem Entwurf; Zuordnungen zu Lehrplänen tragen jeweils ihre eigene Sicherheitsangabe."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-4-language.yaml"}}$J$::jsonb, 'draft'),
  ('b1710e21-762d-5f26-a42a-54bf54e5caa7', v_de, $J$strand$J$, $J$Die Geschichte der Zahlen$J$, $J$Montessoris Fünfte Große Erzählung: wie Menschen dazu kamen, Mengen mit Symbolen darzustellen — Strichlisten, Stellenwertsystem, die Null — als eine historische menschliche Errungenschaft, keine bereits fertige Tatsache der Natur. Der Strang, der eine Behauptung ausdrücklich macht, die dieses Modell als echten Befund behandelt: dass Mathematik, so erzählt, selbst eine der Großen Erzählungen ist.$J$, NULL, $J$Mathematics$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-numbers","sequence":5,"typicalGradeBand":"GB-0–GB-6 (spans all bands via subStrands; Montessori's own claimed scope is GB-1–GB-3, ~ages 6–12)","associatedDomains":["Mathematics","History","Computer Science"],"relations":{"parallel":["OE-STRAND-cosmic-education-k12-story-of-language"]},"homeAnchors":[{"id":"computer-models","label":"Computermodelle","description":"Vereinfachte, regelbasierte Simulationen, mit denen sich komplexe reale Systeme nachbilden und untersuchen lassen."},{"id":"ancient-ancestors","label":"Frühe Vorfahren","description":"Die Ur- und Frühgeschichte des Menschen als Quelle für Perspektive auf die Gegenwart."}],"thinkingTool":{"id":"analogy-mapping","label":"Analogien & Analogie-Mapping","description":"Strukturierter, merkmalsweiser Vergleich, der benennt, was sich entspricht und was nicht — hier überall dort eingesetzt, wo sich das Muster einer Großen Erzählung in einer anderen wiederholt."},"essentialQuestion":{"broad":"Wer hat die Zahlen erfunden, und hätte das Zählen auch anders funktionieren können?","worked":"Ein Zehnersystem mit Stellenwert und einer Null ist nicht die einzige Art, wie Menschen je Mengen dargestellt haben — andere Systeme nutzten andere Basen, kein Stellenwertsystem oder keine Null. Wenn Zahlen selbst eine Geschichte haben und auch anders hätten verlaufen können, was ändert das daran, wie eine Klasse über „Entdecken“ gegenüber „Erfinden“ in der Mathematik denken sollte?"},"ecosystemConnections":[{"id":"numbers-to-osci-synth","repo":"oSci","kind":"structural-parallel","title":"Strukturelle Parallele: oScis rekursive Selektions-Synthese","description":"oScis eigene osci:synth:recursive-selection-mind-curriculum-science verfolgt ein Variations-/Selektions-/Retentions-Muster über individuelle Kognition, kulturelle Wissenssysteme und die Geschichte der Wissenschaft hinweg."},{"id":"numbers-to-strand-204","repo":"oe-interdisciplinary-k12","kind":"structural-parallel","title":"Strukturelle Parallele: Strang 204 von oe-interdisciplinary-k12","description":"Die GB-3-Aussage von Strang 5 — eine neue mathematische Idee baut auf früheren Ideen auf, statt aus dem Nichts zu entstehen — ist eine direkte Anwendung von Strang 204s eigener Darstellung, wie Köpfe und Kulturen nach besseren Ideen suchen."}],"review":{"state":"unreviewed","note":"Beschreibung und Leitfragen stammen aus dem zweisprachigen Entwurf."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-5-numbers.yaml"}}$J$::jsonb, 'draft'),
  ('44cab15a-d14d-5244-9faa-be6d7ee7fa90', v_de, $J$substrand$J$, $J$Wahrnehmen, wie viele$J$, NULL, $J$GB-0$J$, $J$Mathematics$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-numbers-gb0","typicalGradeBand":"GB-0 (~3–6)","gradeBandId":"GB-0","gradeBandLabel":"Frühe Kindheit","approxAge":"3–6","required":false,"concepts":[],"montessoriScope":"informal-precursor","crosswalks":[{"system":"sachsen-lehrplan","systemName":"Sächsischer Lehrplan Grundschule Sachunterricht","systemType":"state-standards","code":"vor der Schulpflicht","note":"Die Kita liegt vor der Schulpflicht und außerhalb des Geltungsbereichs des Sächsischen Lehrplans — auch die eigene GB-0-Stufe dieses Modells ist ein informeller, nicht Montessori-eigener Vorläufer.","noteLanguage":"de","confidence":"confirmed","concepts":[],"appliesToAllStrands":true}],"review":{"state":"unreviewed","note":"Bezeichnung aus dem Entwurf; Zuordnungen zu Lehrplänen tragen jeweils ihre eigene Sicherheitsangabe."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-5-numbers.yaml"}}$J$::jsonb, 'draft'),
