  ('b958bb0f-7f8d-5f57-b8a1-d7027ea2b4b4', v_de, $J$substrand$J$, $J$Mathematik als Große Erzählung$J$, $J$Schlüsselkonzepte: Menge und Symbol, Innovation$J$, $J$GB-3$J$, $J$Mathematics$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-numbers-gb3","typicalGradeBand":"GB-3 (~10–12)","gradeBandId":"GB-3","gradeBandLabel":"Sekundarstufe I (früh)","approxAge":"10–12","required":true,"concepts":[{"id":"OE-CONCEPT-cosmic-k12-quantity-and-symbol","emphasis":"primary"},{"id":"OE-CONCEPT-oe-interdisciplinary-innovation","emphasis":"reinforcing"}],"montessoriScope":"inside","crosswalks":[{"system":"ib-pyp","systemName":"IB Primary Years Programme — Sechs transdisziplinäre Themen","systemType":"state-standards","code":"How We Organize Ourselves","note":"Bestätigte Themenbezeichnung; Zahlensysteme als eine Form organisatorischer Technologie passen zum eigenen Geltungsbereich dieses Themas.","noteLanguage":"de","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-quantity-and-symbol"],"appliesToAllStrands":false},{"system":"sachsen-anhalt-lehrplan","systemName":"Fachlehrplan Grundschule Sachunterricht (Sachsen-Anhalt)","systemType":"state-standards","code":"Mathematische Kompetenz (fachübergreifend, Endniveau Schuljahrgang 4)","note":"Als benannte fachübergreifende Kompetenz bestätigt, die Maßeinheiten, Messungen und Datendarstellung auf reale Sachunterrichtsprobleme anwendet.","noteLanguage":"de","confidence":"uncertain","concepts":["OE-CONCEPT-cosmic-k12-quantity-and-symbol"],"appliesToAllStrands":false}],"review":{"state":"unreviewed","note":"Bezeichnung aus dem Entwurf; Zuordnungen zu Lehrplänen tragen jeweils ihre eigene Sicherheitsangabe."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-5-numbers.yaml"}}$J$::jsonb, 'draft'),
  ('fc6f8f7c-06fd-55a0-8d47-5d2823095b5e', v_de, $J$performance_indicator$J$, $J$Zahlen · GB-3.1$J$, $J$Erklärt an einem echten historischen Beispiel (z. B. Null, negative Zahlen, Algebra), wie eine neue mathematische Idee auf früheren Ideen aufbaute und sie veränderte, statt aus dem Nichts zu erscheinen. Das ist eine Anwendung des Musters „vom nächsten bekannten Fall ausgehen und ihn dann verbessern“, das Strang 204 von oe-interdisciplinary-k12 für individuelles und kulturelles Lernen allgemein entwickelt.$J$, $J$GB-3$J$, $J$Mathematics$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-numbers-gb3#pi1","ordinal":1,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-5-numbers.yaml"}}$J$::jsonb, 'draft'),
  ('c7d84858-72a8-5e67-afe6-d2b9053c41fb', v_de, $J$performance_indicator$J$, $J$Zahlen · GB-3.2$J$, $J$Nimmt zu einer selbst gewählten mathematischen Idee begründet Stellung, ob sie „entdeckt“ wurde (sie war schon immer wahr und wartete darauf, gefunden zu werden) oder „erfunden“ (Menschen haben sie konstruiert und hätten plausibel etwas anderes konstruieren können). Das ist ein ausdrücklicher, altersgerechter erster Kontakt mit einer offenen Frage der Philosophie der Mathematik und keine Antwort, die dieses Modell vorgibt.$J$, $J$GB-3$J$, $J$Mathematics$J$, $J${"source_id":"OE-STRAND-cosmic-education-k12-story-of-numbers-gb3#pi2","ordinal":2,"kind":"observable-performance","review":{"state":"unreviewed","note":"Deutscher Wortlaut von Claude entworfen (2026-11-07), noch von keiner deutschsprachigen Fachperson geprüft."},"_source":{"repo":"cosmic-education-k12","path":"lpm/strands/strand-5-numbers.yaml"}}$J$::jsonb, 'draft'),
